import React, { useState, useEffect } from 'react';
import { onAuthStateChanged, User as FirebaseUser } from 'firebase/auth';
import { doc, getDoc } from 'firebase/firestore';
import { auth, db } from './firebase';
import { UserRole, MainView, User } from './types';
import Navbar from './components/Navbar';
import Sidebar from './components/Sidebar';
import DashboardView from './views/DashboardView';
import ProfessorView from './views/ProfessorView';
import StudentsView from './views/StudentsView';
import SecretariatView from './views/SecretariatView';
import SettingsView from './views/SettingsView';
import LoginView from './views/LoginView';

const App: React.FC = () => {
  const [currentUser, setCurrentUser] = useState<User | null>(null);
  const [loading, setLoading] = useState(true);
  const [activeView, setActiveView] = useState<MainView>('dashboard');
  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);

  useEffect(() => {
    const unsubscribe = onAuthStateChanged(auth, async (user) => {
      if (user) {
        // Fetch role from Firestore
        const userDoc = await getDoc(doc(db, 'usuarios', user.uid));
        const userData = userDoc.data();

        // RBAC Check: Only diretor or professor
        const role = (userData?.role as UserRole) || 'aluno';

        setCurrentUser({
          uid: user.uid,
          email: user.email,
          displayName: user.displayName,
          role: role
        });
      } else {
        setCurrentUser(null);
      }
      setLoading(false);
    });

    return () => unsubscribe();
  }, []);

  if (loading) {
    return (
      <div className="flex h-screen items-center justify-center bg-slate-50">
        <div className="flex flex-col items-center gap-4">
          <div className="h-8 w-8 animate-spin rounded-full border-4 border-indigo-600 border-t-transparent"></div>
          <p className="text-sm font-medium text-slate-600">Carregando sistema...</p>
        </div>
      </div>
    );
  }

  // Unauthorized or not logged in
  if (!currentUser) {
    return <LoginView />;
  }

  // RBAC Access Filter
  if (currentUser.role === 'aluno') {
    return (
      <div className="flex h-screen items-center justify-center p-6 text-center">
        <div className="max-w-md space-y-4">
          <h1 className="text-2xl font-bold text-slate-900">Acesso Restrito</h1>
          <p className="text-slate-600">Este painel é exclusivo para Diretores e Professores. Se você é aluno, acesse o portal do aluno.</p>
          <button 
            onClick={() => auth.signOut()}
            className="rounded-lg bg-indigo-600 px-6 py-2 text-white hover:bg-indigo-700"
          >
            Sair e Voltar
          </button>
        </div>
      </div>
    );
  }

  const renderView = () => {
    switch (activeView) {
      case 'dashboard': return <DashboardView />;
      case 'professor': return <ProfessorView />;
      case 'alunos': return <StudentsView />;
      case 'secretaria': return <SecretariatView />;
      case 'configuracoes': return <SettingsView />;
      default: return <DashboardView />;
    }
  };

  return (
    <div className="min-h-screen bg-slate-50 flex flex-col">
      <Navbar 
        user={currentUser} 
        activeView={activeView} 
        setActiveView={setActiveView} 
        setIsMobileMenuOpen={setIsMobileMenuOpen}
        isMobileMenuOpen={isMobileMenuOpen}
      />

      <main className="flex-1 flex overflow-hidden">
        {/* Render internal sidebar only for specific views that need it (like Professor area) */}
        {activeView === 'professor' && <Sidebar activeView={activeView} />}

        <div className="flex-1 overflow-y-auto p-4 md:p-8">
          <div className="max-w-7xl mx-auto">
            {renderView()}
          </div>
        </div>
      </main>
    </div>
  );
};

export default App;

import React from 'react';
