    { id: 'alunos', label: 'Alunos', icon: <GraduationCap size={18} /> },
    { id: 'secretaria', label: 'Secretaria', icon: <MessageSquare size={18} /> },
    { id: 'configuracoes', label: 'Configurações', icon: <Settings size={18} /> },
  ];

  return (
    <nav className="sticky top-0 z-50 bg-slate-900 text-slate-300 h-16 shadow-lg">
      <div className="max-w-[1440px] mx-auto px-4 h-full flex items-center justify-between">
        {/* Brand */}
        <div className="flex items-center gap-2">
          <div className="bg-indigo-600 text-white p-1.5 rounded-lg">
            <BookOpen size={20} />
          </div>
          <span className="font-bold text-white text-lg tracking-tight hidden sm:block">Escola Bíblica EAD</span>
        </div>

        {/* Desktop Nav */}
        <div className="hidden md:flex items-center gap-1">
          {menuItems.map((item) => (
            <button
              key={item.id}
              onClick={() => setActiveView(item.id)}
              className={`flex items-center gap-2 px-4 py-2 rounded-md transition-all text-sm font-medium ${
                activeView === item.id 
                  ? 'bg-slate-800 text-white border-b-2 border-indigo-500' 
                  : 'hover:bg-slate-800 hover:text-slate-100'
              }`}
            >
              {item.icon}
              {item.label}
            </button>
          ))}
        </div>

        {/* User / Logout */}
        <div className="flex items-center gap-4">
          <div className="hidden sm:flex flex-col items-end">
            <span className="text-xs font-semibold text-white leading-none">{user.displayName || user.email}</span>
            <span className="text-[10px] uppercase text-indigo-400 font-bold">{user.role}</span>
          </div>
          <button 
            onClick={() => auth.signOut()}
            className="p-2 hover:bg-slate-800 rounded-full text-slate-400 hover:text-white"
            title="Sair"
          >
            <LogOut size={18} />
          </button>

          {/* Mobile Menu Toggle */}
          <button 
            className="md:hidden p-2 text-slate-300"
            onClick={() => setIsMobileMenuOpen(!isMobileMenuOpen)}
          >
            {isMobileMenuOpen ? <X size={24} /> : <Menu size={24} />}
          </button>
        </div>
      </div>

      {/* Mobile Menu Overlay */}
      {isMobileMenuOpen && (
        <div className="absolute top-16 left-0 w-full bg-slate-900 border-t border-slate-800 md:hidden animate-in slide-in-from-top-4">
          <div className="flex flex-col p-4 gap-2">
            {menuItems.map((item) => (
              <button
                key={item.id}
                onClick={() => {
                  setActiveView(item.id);
                  setIsMobileMenuOpen(false);
                }}
                className={`flex items-center gap-3 w-full px-4 py-3 rounded-lg text-sm font-medium ${
                  activeView === item.id ? 'bg-indigo-600 text-white' : 'hover:bg-slate-800'
                }`}
              >
                {item.icon}
                {item.label}
              </button>
            ))}
          </div>
        </div>
      )}
