import React, { useState, useEffect } from 'react';
import { collection, query, limit, getDocs, orderBy } from 'firebase/firestore';
import { db } from '../firebase';
import { Course } from '../types';
import { Users, FileBadge, Activity, MoreVertical, Plus } from 'lucide-react';

const DashboardView: React.FC = () => {
  const [courses, setCourses] = useState<Course[]>([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const fetchCourses = async () => {
      try {
        const q = query(collection(db, 'cursos'), orderBy('createdAt', 'desc'), limit(5));
        const querySnapshot = await getDocs(q);
        const fetchedCourses: Course[] = [];
        querySnapshot.forEach((doc) => {
          fetchedCourses.push({ id: doc.id, ...doc.data() } as Course);
        });
        setCourses(fetchedCourses);
      } catch (error) {
        console.error("Error fetching courses:", error);
      } finally {
        setLoading(false);
      }
    };

    fetchCourses();
  }, []);

  const stats = [
    { label: 'Alunos Ativos', value: '1.248', icon: <Users className="text-indigo-600" />, trend: '+12%' },
    { label: 'Certificados Emitidos', value: '382', icon: <FileBadge className="text-amber-600" />, trend: '+5%' },
    { label: 'Engajamento Médio', value: '84%', icon: <Activity className="text-emerald-600" />, trend: '+2%' },
  ];

  return (
    <div className="space-y-6">
      <header className="flex items-center justify-between">
        <div>
          <h1 className="text-2xl font-bold text-slate-900">Visão Geral</h1>
          <p className="text-slate-500 text-sm">Bem-vindo ao painel de controle da Escola Bíblica EAD.</p>
        </div>
        <button className="flex items-center gap-2 bg-indigo-600 text-white px-4 py-2 rounded-lg text-sm font-semibold hover:bg-indigo-700 transition-colors shadow-sm">
          <Plus size={18} />
          Novo Curso
        </button>
      </header>

      {/* Metrics */}
      <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
        {stats.map((stat, i) => (
          <div key={i} className="bg-white p-5 rounded-xl border border-slate-200 shadow-sm flex items-start justify-between">
            <div>
              <p className="text-xs font-bold text-slate-400 uppercase tracking-wider mb-1">{stat.label}</p>
              <h3 className="text-2xl font-bold text-slate-900">{stat.value}</h3>
              <span className="text-xs font-medium text-emerald-600 mt-1 inline-block">{stat.trend} este mês</span>
            </div>
            <div className="p-3 bg-slate-50 rounded-lg">{stat.icon}</div>
          </div>
        ))}
      </div>

      {/* Courses List */}
      <div className="bg-white rounded-xl border border-slate-200 shadow-sm overflow-hidden">
        <div className="px-6 py-4 border-b border-slate-100 flex items-center justify-between">
          <h2 className="font-bold text-slate-800">Cursos Recentes</h2>
          <button className="text-xs font-semibold text-indigo-600 hover:underline">Ver todos</button>
        </div>

        {loading ? (
          <div className="p-8 flex justify-center">
            <div className="h-6 w-6 animate-spin rounded-full border-2 border-indigo-600 border-t-transparent"></div>
          </div>
        ) : courses.length > 0 ? (
          <div className="overflow-x-auto">
            <table className="w-full text-left">
              <thead>
                <tr className="bg-slate-50 text-[10px] uppercase tracking-widest text-slate-500 font-bold">
                  <th className="px-6 py-3">Curso</th>
                  <th className="px-6 py-3">Alunos</th>
                  <th className="px-6 py-3">Status</th>
                  <th className="px-6 py-3 text-right">Ações</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-slate-100">
                {courses.map((course) => (
                  <tr key={course.id} className="hover:bg-slate-50 transition-colors">
                    <td className="px-6 py-4">
                      <div className="flex flex-col">
                        <span className="text-sm font-semibold text-slate-900">{course.nome}</span>
                        <span className="text-xs text-slate-500 truncate max-w-[200px]">{course.descricao || 'Sem descrição'}</span>
                      </div>
                    </td>
                    <td className="px-6 py-4 text-sm text-slate-600">{course.inscritos} inscritos</td>
                    <td className="px-6 py-4">
                      <span className={`inline-flex items-center px-2 py-0.5 rounded text-[10px] font-bold uppercase ${
                        course.status === 'ativo' ? 'bg-emerald-100 text-emerald-700' : 'bg-amber-100 text-amber-700'
                      }`}>
                        {course.status}
                      </span>
                    </td>
                    <td className="px-6 py-4 text-right">
                      <button className="p-1 hover:bg-slate-200 rounded text-slate-400">
                        <MoreVertical size={16} />
                      </button>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        ) : (
          <div className="p-12 text-center">
            <p className="text-slate-500 text-sm">Nenhum curso encontrado na coleção 'cursos'.</p>
          </div>
        )}
      </div>
    </div>
  );
};

export default DashboardView;

