  useEffect(() => {
    const fetchMyCourses = async () => {
      try {
        // Filtro preparado: Busca cursos onde o professorId corresponde ao UID do usuário logado
        const q = query(collection(db, 'cursos'), where('professorId', '==', user.uid));
