import React, { useState, useEffect } from 'react';
import { 
  collection, 
  query, 
  where, 
  getDocs, 
  addDoc, 
  serverTimestamp, 
  orderBy,
  doc,
  getDoc
} from 'firebase/firestore';
import { db } from '../firebase';
import { Course, Module, Lesson, User } from '../types';
import { 
  Search, 
  Filter, 
  BookOpen, 
  Plus, 
  Info, 
  X, 
  ChevronRight, 
  Play, 
  FileText, 
  MoreVertical,
  ArrowLeft,
  Layout
} from 'lucide-react';

interface ProfessorViewProps {
  user: User;
}

const ProfessorView: React.FC<ProfessorViewProps> = ({ user }) => {
  const [myCourses, setMyCourses] = useState<Course[]>([]);
  const [loading, setLoading] = useState(true);
  const [selectedCourse, setSelectedCourse] = useState<Course | null>(null);
  const [modules, setModules] = useState<Module[]>([]);
  const [lessonsByModule, setLessonsByModule] = useState<Record<string, Lesson[]>>({});

  // Modal States
  const [showCourseModal, setShowCourseModal] = useState(false);
  const [showModuleModal, setShowModuleModal] = useState(false);
  const [showLessonModal, setShowLessonModal] = useState(false);
  const [activeModuleId, setActiveModuleId] = useState<string | null>(null);

  // Form States
  const [courseForm, setCourseForm] = useState({
    nome: '',
    descricao: '',
    capaUrl: '',
    cargaHoraria: '',
    publicoAlvo: 'Geral' as const
  });
  const [moduleForm, setModuleForm] = useState({ nome: '' });
  const [lessonForm, setLessonForm] = useState({
    titulo: '',
    videoUrl: '',
    materialUrl: ''
  });

  const fetchMyCourses = async () => {
    setLoading(true);
    try {
      const q = query(collection(db, 'cursos'), where('professorId', '==', user.uid), orderBy('createdAt', 'desc'));
      const querySnapshot = await getDocs(q);
      const fetched: Course[] = [];
      querySnapshot.forEach((doc) => {
        fetched.push({ id: doc.id, ...doc.data() } as Course);
      });
      setMyCourses(fetched);
    } catch (error) {
      console.error("Erro ao carregar seus cursos:", error);
    } finally {
      setLoading(false);
    }
  };

  const fetchModules = async (courseId: string) => {
    try {
      const q = query(collection(db, 'cursos', courseId, 'modulos'), orderBy('ordem', 'asc'));
      const querySnapshot = await getDocs(q);
      const fetched: Module[] = [];
      querySnapshot.forEach((doc) => {
        fetched.push({ id: doc.id, ...doc.data() } as Module);
      });
      setModules(fetched);

      // Fetch lessons for each module
      for (const mod of fetched) {
        fetchLessons(courseId, mod.id);
      }
    } catch (error) {
      console.error("Erro ao carregar módulos:", error);
    }
  };

  const fetchLessons = async (courseId: string, moduleId: string) => {
    try {
      const q = query(collection(db, 'cursos', courseId, 'modulos', moduleId, 'aulas'), orderBy('ordem', 'asc'));
      const querySnapshot = await getDocs(q);
      const fetched: Lesson[] = [];
      querySnapshot.forEach((doc) => {
        fetched.push({ id: doc.id, ...doc.data() } as Lesson);
      });
      setLessonsByModule(prev => ({ ...prev, [moduleId]: fetched }));
    } catch (error) {
      console.error("Erro ao carregar aulas:", error);
    }
  };

  useEffect(() => {
    fetchMyCourses();
  }, [user.uid]);

  const handleCreateCourse = async (e: React.FormEvent) => {
    e.preventDefault();
    try {
      await addDoc(collection(db, 'cursos'), {
        ...courseForm,
        professorId: user.uid,
        inscritos: 0,
        status: 'rascunho',
        createdAt: serverTimestamp()
      });
      setShowCourseModal(false);
      setCourseForm({ nome: '', descricao: '', capaUrl: '', cargaHoraria: '', publicoAlvo: 'Geral' });
      fetchMyCourses();
    } catch (error) {
      console.error("Erro ao criar curso:", error);
    }
  };

  const handleCreateModule = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!selectedCourse) return;
    try {
      await addDoc(collection(db, 'cursos', selectedCourse.id, 'modulos'), {
        nome: moduleForm.nome,
        ordem: modules.length + 1,
        createdAt: serverTimestamp()
      });
      setShowModuleModal(false);
      setModuleForm({ nome: '' });
      fetchModules(selectedCourse.id);
    } catch (error) {
      console.error("Erro ao criar módulo:", error);
    }
  };

  const handleCreateLesson = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!selectedCourse || !activeModuleId) return;
    try {
      const currentLessonsCount = lessonsByModule[activeModuleId]?.length || 0;
      await addDoc(collection(db, 'cursos', selectedCourse.id, 'modulos', activeModuleId, 'aulas'), {
        ...lessonForm,
        ordem: currentLessonsCount + 1,
        createdAt: serverTimestamp()
      });
      setShowLessonModal(false);
      setLessonForm({ titulo: '', videoUrl: '', materialUrl: '' });
      fetchLessons(selectedCourse.id, activeModuleId);
    } catch (error) {
      console.error("Erro ao criar aula:", error);
    }
  };

  const openCourseDetail = (course: Course) => {
    setSelectedCourse(course);
    fetchModules(course.id);
  };

  if (selectedCourse) {
    return (
      <div className="space-y-6 animate-in fade-in duration-500">
        <header className="flex items-center gap-4">
          <button 
            onClick={() => setSelectedCourse(null)}
            className="p-2 hover:bg-slate-200 rounded-lg text-slate-600 transition-colors"
          >
            <ArrowLeft size={20} />
          </button>
          <div>
            <h1 className="text-2xl font-bold text-slate-900">{selectedCourse.nome}</h1>
            <p className="text-slate-500 text-sm">Gerenciando Módulos e Aulas</p>
          </div>
        </header>

        <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
          <div className="lg:col-span-2 space-y-4">
            <div className="bg-white rounded-2xl border border-slate-200 shadow-sm overflow-hidden">
              <div className="px-6 py-4 border-b border-slate-100 flex items-center justify-between bg-slate-50/50">
                <h2 className="text-sm font-bold text-slate-800 uppercase tracking-wider">Estrutura de Ensino</h2>
                <button 
                  onClick={() => setShowModuleModal(true)}
                  className="flex items-center gap-2 text-indigo-600 text-xs font-bold hover:underline"
                >
                  <Plus size={14} /> Adicionar Módulo
                </button>
              </div>

              <div className="p-4 space-y-4">
                {modules.length === 0 ? (
                  <div className="p-12 text-center text-slate-400 italic text-sm">
                    Nenhum módulo cadastrado para este curso.
                  </div>
                ) : (
                  modules.map((mod) => (
                    <div key={mod.id} className="border border-slate-100 rounded-xl overflow-hidden bg-slate-50/30">
                      <div className="px-4 py-3 border-b border-slate-100 flex items-center justify-between bg-white">
                        <div className="flex items-center gap-3">
                          <span className="bg-slate-100 text-slate-500 w-6 h-6 rounded flex items-center justify-center text-[10px] font-bold">
                            {mod.ordem}
                          </span>
                          <h3 className="font-bold text-slate-800 text-sm">{mod.nome}</h3>
                        </div>
                        <button 
                          onClick={() => { setActiveModuleId(mod.id); setShowLessonModal(true); }}
                          className="p-1.5 text-indigo-600 hover:bg-indigo-50 rounded-lg transition-colors"
                          title="Adicionar Aula"
                        >
                          <Plus size={18} />
                        </button>
                      </div>

                      <div className="p-2 space-y-1">
                        {lessonsByModule[mod.id]?.map((lesson) => (
                          <div key={lesson.id} className="flex items-center justify-between p-3 rounded-lg hover:bg-white hover:shadow-sm transition-all group">
                            <div className="flex items-center gap-4">
                              <div className="p-2 bg-indigo-50 text-indigo-600 rounded">
                                <Play size={14} fill="currentColor" />
                              </div>
                              <div>
                                <p className="text-sm font-semibold text-slate-700">{lesson.titulo}</p>
                                <div className="flex items-center gap-3 mt-0.5">
                                  {lesson.videoUrl && <span className="text-[10px] text-slate-400 flex items-center gap-1"><Play size={10} /> Vídeo</span>}
                                  {lesson.materialUrl && <span className="text-[10px] text-slate-400 flex items-center gap-1"><FileText size={10} /> PDF</span>}
                                </div>
                              </div>
                            </div>
                            <button className="opacity-0 group-hover:opacity-100 p-1 text-slate-300 hover:text-slate-600 transition-all">
                              <MoreVertical size={16} />
                            </button>
                          </div>
                        ))}
                        {(!lessonsByModule[mod.id] || lessonsByModule[mod.id].length === 0) && (
                          <p className="p-4 text-center text-xs text-slate-400 italic">Sem aulas neste módulo.</p>
                        )}
                      </div>
                    </div>
                  ))
                )}
              </div>
            </div>
          </div>

          <div className="space-y-4">
            <div className="bg-white p-6 rounded-2xl border border-slate-200 shadow-sm">
              <img 
                src={selectedCourse.capaUrl || 'https://images.unsplash.com/photo-1504052434139-443c40c98408?w=800&auto=format&fit=crop&q=60'} 
                alt="Capa"
                className="w-full h-40 object-cover rounded-xl mb-4 bg-slate-100"
              />
              <div className="space-y-3">
                <div className="flex justify-between text-xs">
                  <span className="text-slate-500 font-bold uppercase">Carga Horária</span>
                  <span className="text-slate-900 font-bold">{selectedCourse.cargaHoraria}</span>
                </div>
                <div className="flex justify-between text-xs">
                  <span className="text-slate-500 font-bold uppercase">Público</span>
                  <span className="text-indigo-600 font-bold">{selectedCourse.publicoAlvo}</span>
                </div>
                <div className="flex justify-between text-xs">
                  <span className="text-slate-500 font-bold uppercase">Status</span>
                  <span className={`px-2 py-0.5 rounded text-[10px] font-bold uppercase ${selectedCourse.status === 'ativo' ? 'bg-emerald-100 text-emerald-700' : 'bg-slate-100 text-slate-600'}`}>
                    {selectedCourse.status}
                  </span>
                </div>
              </div>
              <button className="w-full mt-6 bg-slate-900 text-white py-2 rounded-xl text-xs font-bold hover:bg-slate-800 transition-all">
                Editar Informações Básicas
              </button>
            </div>
          </div>
        </div>

        {/* Modal Módulo */}
        {showModuleModal && (
          <div className="fixed inset-0 z-[110] flex items-center justify-center p-4 bg-slate-900/40 backdrop-blur-sm">
            <div className="bg-white w-full max-w-md rounded-2xl shadow-2xl overflow-hidden animate-in zoom-in-95 duration-200">
              <div className="p-4 border-b border-slate-100 flex items-center justify-between">
                <h3 className="font-bold text-slate-900">Novo Módulo</h3>
                <button onClick={() => setShowModuleModal(false)} className="text-slate-400 hover:text-slate-600"><X size={20} /></button>
              </div>
              <form onSubmit={handleCreateModule} className="p-6 space-y-4">
                <div className="space-y-1.5">
                  <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Nome do Módulo</label>
                  <input 
                    required
                    value={moduleForm.nome}
                    onChange={e => setModuleForm({nome: e.target.value})}
                    placeholder="Ex: Módulo 1: Introdução"
                    className="w-full px-4 py-2 bg-slate-50 border border-slate-200 rounded-xl text-sm outline-none focus:ring-2 focus:ring-indigo-500 transition-all"
                  />
                </div>
                <button type="submit" className="w-full bg-indigo-600 text-white py-2.5 rounded-xl font-bold text-sm shadow-lg shadow-indigo-200 hover:bg-indigo-700 transition-all">
                  Salvar Módulo
                </button>
              </form>
            </div>
          </div>
        )}

        {/* Modal Aula */}
        {showLessonModal && (
          <div className="fixed inset-0 z-[110] flex items-center justify-center p-4 bg-slate-900/40 backdrop-blur-sm">
            <div className="bg-white w-full max-w-lg rounded-2xl shadow-2xl overflow-hidden animate-in zoom-in-95 duration-200">
              <div className="p-4 border-b border-slate-100 flex items-center justify-between">
                <h3 className="font-bold text-slate-900">Adicionar Aula</h3>
                <button onClick={() => setShowLessonModal(false)} className="text-slate-400 hover:text-slate-600"><X size={20} /></button>
              </div>
              <form onSubmit={handleCreateLesson} className="p-6 space-y-4">
                <div className="space-y-1.5">
                  <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Título da Aula</label>
                  <input 
                    required
                    value={lessonForm.titulo}
                    onChange={e => setLessonForm({...lessonForm, titulo: e.target.value})}
                    placeholder="Ex: Aula 01 - Contexto Histórico"
                    className="w-full px-4 py-2 bg-slate-50 border border-slate-200 rounded-xl text-sm outline-none focus:ring-2 focus:ring-indigo-500 transition-all"
                  />
