                <div className="grid grid-cols-2 gap-4">
                  <div className="space-y-1.5">
                    <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Carga Horária Total</label>
                    <input 
                      required
                      value={courseForm.cargaHoraria}
                      onChange={e => setCourseForm({...courseForm, cargaHoraria: e.target.value})}
                      placeholder="Ex: 40h"
                      className="w-full px-4 py-3 bg-slate-50 border border-slate-200 rounded-xl text-sm outline-none focus:ring-2 focus:ring-indigo-500 transition-all font-medium"
                    />
