                      className="w-full px-4 py-3 bg-slate-50 border border-slate-200 rounded-xl text-sm outline-none focus:ring-2 focus:ring-indigo-500 transition-all font-bold text-slate-700"
                    >
                      <option value="Geral">Geral (Toda a Igreja)</option>
