                  <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Título do Módulo</label>
                  <input 
                    required
                    autoFocus
                    value={moduleForm.nome}
                    onChange={e => setModuleForm({nome: e.target.value})}
                    placeholder="Ex: Módulo 1: Introdução ao Antigo Testamento"
                    className="w-full px-4 py-2.5 bg-slate-50 border border-slate-200 rounded-xl text-sm outline-none focus:ring-2 focus:ring-indigo-500 transition-all"
                  />
                  <p className="text-[10px] text-slate-400">O módulo será adicionado ao final da lista de ordem atual.</p>
                </div>
                <div className="flex gap-3 pt-2">
                  <button 
                    type="button" 
                    onClick={() => setShowModuleModal(false)}
                    className="flex-1 px-4 py-2.5 border border-slate-200 rounded-xl text-sm font-bold text-slate-600 hover:bg-slate-50"
                  >
                    Cancelar
                  </button>
                  <button type="submit" className="flex-[2] bg-indigo-600 text-white py-2.5 rounded-xl font-bold text-sm shadow-lg shadow-indigo-200 hover:bg-indigo-700 transition-all">
                    Criar Módulo
                  </button>
                </div>
              </form>
            </div>
          </div>
        )}

        {/* Modal Aula */}
        {showLessonModal && (
          <div className="fixed inset-0 z-[110] flex items-center justify-center p-4 bg-slate-900/40 backdrop-blur-sm animate-in fade-in duration-200">
            <div className="bg-white w-full max-w-lg rounded-2xl shadow-2xl overflow-hidden animate-in zoom-in-95 duration-200">
              <div className="p-4 border-b border-slate-100 flex items-center justify-between bg-slate-50/50">
                <div className="flex items-center gap-2">
                  <Play size={18} fill="currentColor" className="text-indigo-600" />
                  <h3 className="font-bold text-slate-900">Adicionar Novo Conteúdo</h3>
                </div>
                <button onClick={() => setShowLessonModal(false)} className="text-slate-400 hover:text-slate-600"><X size={20} /></button>
              </div>
              <form onSubmit={handleCreateLesson} className="p-6 space-y-4">
                <div className="space-y-1.5">
                  <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Título da Aula</label>
                  <input 
                    required
                    autoFocus
                    value={lessonForm.titulo}
                    onChange={e => setLessonForm({...lessonForm, titulo: e.target.value})}
                    placeholder="Ex: Aula 01 - Contexto Histórico e Geográfico"
                    className="w-full px-4 py-2.5 bg-slate-50 border border-slate-200 rounded-xl text-sm outline-none focus:ring-2 focus:ring-indigo-500 transition-all"
                  />
                </div>
                <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                  <div className="space-y-1.5">
                    <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Link de Vídeo (ID ou URL)</label>
                    <input 
                      value={lessonForm.videoUrl}
                      onChange={e => setLessonForm({...lessonForm, videoUrl: e.target.value})}
                      placeholder="YouTube / Vimeo"
                      className="w-full px-4 py-2 bg-slate-50 border border-slate-200 rounded-xl text-sm outline-none focus:ring-2 focus:ring-indigo-500 transition-all"
                    />
                  </div>
                  <div className="space-y-1.5">
                    <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Material de Apoio (PDF/Link)</label>
                    <input 
                      value={lessonForm.materialUrl}
                      onChange={e => setLessonForm({...lessonForm, materialUrl: e.target.value})}
                      placeholder="Drive / Dropbox"
                      className="w-full px-4 py-2 bg-slate-50 border border-slate-200 rounded-xl text-sm outline-none focus:ring-2 focus:ring-indigo-500 transition-all"
                    />
                  </div>
