          <Plus size={18} />
          Cadastrar Novo Curso
        </button>
      </header>

      <div className="bg-indigo-50 border border-indigo-100 p-4 rounded-xl flex gap-3 items-start">
        <Info className="text-indigo-600 mt-0.5 shrink-0" size={18} />
        <div>
          <p className="text-sm font-semibold text-indigo-900 leading-none mb-1">Filtro Ativo</p>
          <p className="text-xs text-indigo-700">Você está visualizando apenas os cursos sob sua responsabilidade direta ({user.displayName}).</p>
