                    <div className="space-y-6">
                      <div className={`p-4 rounded-xl border transition-all ${isTimerFinished ? 'bg-emerald-50 border-emerald-100' : 'bg-amber-50 border-amber-100'}`}>
                        <div className="flex items-center gap-3 mb-2">
                          {isTimerFinished ? (
                            <div className="bg-emerald-500 text-white p-1 rounded-full"><ChevronRight size={14} /></div>
                          ) : (
                            <Clock size={18} className="text-amber-600 animate-pulse" />
                          )}
