import React, { useState, useEffect, useRef } from 'react';
import { 
  collection, 
  query, 
  where, 
  getDocs, 
  addDoc, 
  deleteDoc,
  serverTimestamp, 
  orderBy,
  doc,
  updateDoc
} from 'firebase/firestore';
import { db } from '../firebase';
import { Course, Module, Lesson, User } from '../types';
import { 
  Search, 
  Plus, 
  X, 
  ChevronRight, 
  Play, 
  Pause,
  Volume2,
  VolumeX,
  Maximize,
  FileText, 
  ArrowLeft, 
  Layout, 
  Trash2, 
  Layers, 
  Eye, 
  Clock, 
  Download, 
  CheckCircle,
  Edit2,
  Save,
  ChevronUp,
  ChevronDown
} from 'lucide-react';

interface ProfessorViewProps {
  user: User;
}

const ProfessorView: React.FC<ProfessorViewProps> = ({ user }) => {
  const [myCourses, setMyCourses] = useState<Course[]>([]);
  const [loading, setLoading] = useState(true);
  const [selectedCourse, setSelectedCourse] = useState<Course | null>(null);
  const [modules, setModules] = useState<Module[]>([]);
  const [lessonsByModule, setLessonsByModule] = useState<Record<string, Lesson[]>>({});

  // Modal/Edit States
  const [showCourseModal, setShowCourseModal] = useState(false);
  const [showLessonModal, setShowLessonModal] = useState(false);
  const [activeModuleId, setActiveModuleId] = useState<string | null>(null);
  const [isEditingCourse, setIsEditingCourse] = useState(false);
  const [editingModuleId, setEditingModuleId] = useState<string | null>(null);
  const [moduleEditName, setModuleEditName] = useState('');

  // Preview States
  const [previewLesson, setPreviewLesson] = useState<Lesson | null>(null);
  const [countdown, setCountdown] = useState(15);
  const [isTimerFinished, setIsTimerFinished] = useState(false);
  const [isConcluded, setIsConcluded] = useState(false);

  // Custom Player States
  const [playerIsPlaying, setPlayerIsPlaying] = useState(false);
  const [playerVolume, setPlayerVolume] = useState(80);
  const [isMuted, setIsMuted] = useState(false);
  const iframeRef = useRef<HTMLIFrameElement>(null);
  const playerContainerRef = useRef<HTMLDivElement>(null);

  // Form States
  const [courseForm, setCourseForm] = useState({
    nome: '',
    descricao: '',
    capaUrl: '',
    cargaHoraria: '',
    publicoAlvo: 'Geral' as const
  });
  const [selectedCourseEdit, setSelectedCourseEdit] = useState({
    nome: '',
    descricao: '',
    capaUrl: '',
    cargaHoraria: '',
    publicoAlvo: 'Geral' as const
  });
  const [lessonForm, setLessonForm] = useState({
    titulo: '',
    videoUrl: '',
    materialUrl: ''
  });

  const fetchMyCourses = async () => {
    setLoading(true);
    try {
      const q = query(collection(db, 'cursos'), where('professorId', '==', user.uid), orderBy('createdAt', 'desc'));
      const querySnapshot = await getDocs(q);
      const fetched: Course[] = [];
      querySnapshot.forEach((doc) => {
        fetched.push({ id: doc.id, ...doc.data() } as Course);
      });
      setMyCourses(fetched);
    } catch (error) {
      console.error("Erro ao carregar seus cursos:", error);
    } finally {
      setLoading(false);
    }
  };

  const fetchModules = async (courseId: string) => {
    try {
      const q = query(collection(db, 'cursos', courseId, 'modulos'), orderBy('ordem', 'asc'));
      const querySnapshot = await getDocs(q);
      const fetched: Module[] = [];
      querySnapshot.forEach((doc) => {
        fetched.push({ id: doc.id, ...doc.data() } as Module);
      });
      setModules(fetched);

      for (const mod of fetched) {
        fetchLessons(courseId, mod.id);
      }
    } catch (error) {
      console.error("Erro ao carregar módulos:", error);
    }
  };

  const fetchLessons = async (courseId: string, moduleId: string) => {
    try {
      const q = query(collection(db, 'cursos', courseId, 'modulos', moduleId, 'aulas'), orderBy('ordem', 'asc'));
      const querySnapshot = await getDocs(q);
      const fetched: Lesson[] = [];
      querySnapshot.forEach((doc) => {
        fetched.push({ id: doc.id, ...doc.data() } as Lesson);
      });
      setLessonsByModule(prev => ({ ...prev, [moduleId]: fetched }));
    } catch (error) {
      console.error("Erro ao carregar aulas:", error);
    }
  };

  useEffect(() => {
    fetchMyCourses();
  }, [user.uid]);

  useEffect(() => {
    let timer: number | undefined;
    if (previewLesson && countdown > 0 && !isConcluded) {
      timer = window.setInterval(() => {
        setCountdown((prev) => {
          if (prev <= 1) {
            setIsTimerFinished(true);
            if (timer) clearInterval(timer);
            return 0;
          }
          return prev - 1;
        });
      }, 1000);
    }
    return () => { if (timer) clearInterval(timer); };
  }, [previewLesson, countdown, isConcluded]);

  // PLAYER COMMANDS
  const sendPlayerCommand = (func: string, args: any[] = []) => {
    if (iframeRef.current && iframeRef.current.contentWindow) {
      iframeRef.current.contentWindow.postMessage(JSON.stringify({ event: 'command', func, args }), '*');
    }
  };

  const togglePlay = () => {
    if (playerIsPlaying) sendPlayerCommand('pauseVideo');
    else sendPlayerCommand('playVideo');
    setPlayerIsPlaying(!playerIsPlaying);
  };

  const toggleMute = () => {
    if (isMuted) {
      sendPlayerCommand('unMute');
      sendPlayerCommand('setVolume', [playerVolume]);
    } else sendPlayerCommand('mute');
    setIsMuted(!isMuted);
  };

  const handleVolumeChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const vol = parseInt(e.target.value);
    setPlayerVolume(vol);
    if (!isMuted) sendPlayerCommand('setVolume', [vol]);
  };

  const toggleFullscreen = () => {
    if (playerContainerRef.current) {
      if (!document.fullscreenElement) playerContainerRef.current.requestFullscreen();
      else document.exitFullscreen();
    }
  };

  // CRUD HANDLERS
  const handleCreateCourse = async (e: React.FormEvent) => {
    e.preventDefault();
    try {
      await addDoc(collection(db, 'cursos'), {
        ...courseForm,
        professorId: user.uid,
        inscritos: 0,
        status: 'rascunho',
        createdAt: serverTimestamp()
      });
      setShowCourseModal(false);
      setCourseForm({ nome: '', descricao: '', capaUrl: '', cargaHoraria: '', publicoAlvo: 'Geral' });
      fetchMyCourses();
    } catch (error) { console.error(error); }
  };

  const handleUpdateCourse = async () => {
    if (!selectedCourse) return;
    try {
      await updateDoc(doc(db, 'cursos', selectedCourse.id), selectedCourseEdit);
      setSelectedCourse({ ...selectedCourse, ...selectedCourseEdit });
      setIsEditingCourse(false);
      fetchMyCourses();
    } catch (error) { console.error(error); }
  };

  const handleCreateModule = async () => {
    if (!selectedCourse) return;
    const moduleName = prompt("Nome do novo módulo:");
    if (!moduleName) return;
    try {
      await addDoc(collection(db, 'cursos', selectedCourse.id, 'modulos'), {
        nome: moduleName,
        ordem: modules.length + 1,
        createdAt: serverTimestamp()
      });
      fetchModules(selectedCourse.id);
    } catch (error) { console.error(error); }
  };

  const handleUpdateModule = async (moduleId: string) => {
    if (!selectedCourse || !moduleEditName) return;
    try {
      await updateDoc(doc(db, 'cursos', selectedCourse.id, 'modulos', moduleId), {
        nome: moduleEditName
      });
      setEditingModuleId(null);
      fetchModules(selectedCourse.id);
    } catch (error) { console.error(error); }
  };

  const handleReorderModule = async (moduleId: string, direction: 'up' | 'down') => {
    if (!selectedCourse) return;
    const currentIndex = modules.findIndex(m => m.id === moduleId);
    const targetIndex = direction === 'up' ? currentIndex - 1 : currentIndex + 1;
    if (targetIndex < 0 || targetIndex >= modules.length) return;

    const currentModule = modules[currentIndex];
    const targetModule = modules[targetIndex];

    try {
      await updateDoc(doc(db, 'cursos', selectedCourse.id, 'modulos', currentModule.id), { ordem: targetModule.ordem });
      await updateDoc(doc(db, 'cursos', selectedCourse.id, 'modulos', targetModule.id), { ordem: currentModule.ordem });
      fetchModules(selectedCourse.id);
    } catch (error) { console.error(error); }
  };

  const handleDeleteModule = async (moduleId: string) => {
    if (!selectedCourse) return;
    if (!confirm("Excluir este módulo e todas as suas aulas?")) return;
    try {
      await deleteDoc(doc(db, 'cursos', selectedCourse.id, 'modulos', moduleId));
      fetchModules(selectedCourse.id);
    } catch (error) { console.error(error); }
  };

  const handleCreateLesson = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!selectedCourse || !activeModuleId) return;
    try {
      const currentLessonsCount = lessonsByModule[activeModuleId]?.length || 0;
      await addDoc(collection(db, 'cursos', selectedCourse.id, 'modulos', activeModuleId, 'aulas'), {
        ...lessonForm,
        ordem: currentLessonsCount + 1,
        createdAt: serverTimestamp()
      });
      setShowLessonModal(false);
      setLessonForm({ titulo: '', videoUrl: '', materialUrl: '' });
      fetchLessons(selectedCourse.id, activeModuleId);
    } catch (error) { console.error(error); }
  };

  const handleDeleteLesson = async (moduleId: string, lessonId: string) => {
    if (!selectedCourse) return;
    if (!confirm("Excluir esta aula?")) return;
    try {
      await deleteDoc(doc(db, 'cursos', selectedCourse.id, 'modulos', moduleId, 'aulas', lessonId));
      fetchLessons(selectedCourse.id, moduleId);
    } catch (error) { console.error(error); }
  };

  const openCourseDetail = (course: Course) => {
    setSelectedCourse(course);
    setSelectedCourseEdit({
      nome: course.nome,
      descricao: course.descricao || '',
      capaUrl: course.capaUrl || '',
      cargaHoraria: course.cargaHoraria,
      publicoAlvo: course.publicoAlvo
    });
    fetchModules(course.id);
  };

  const openPreview = (lesson: Lesson) => {
    setCountdown(15);
    setIsTimerFinished(false);
    setIsConcluded(false);
    setPlayerIsPlaying(false);
    setPreviewLesson(lesson);
  };

  const closePreview = () => {
    setPreviewLesson(null);
    setIsTimerFinished(false);
    setIsConcluded(false);
    setCountdown(15);
    setPlayerIsPlaying(false);
  };

  const handleConcludeLesson = () => {
    if (!isTimerFinished) return;
    setIsConcluded(true);
  };

  const getEmbedUrl = (url: string) => {
    if (!url) return "";
    const ytRegex = /(?:https?:\/\/)?(?:www\.)?(?:youtube\.com\/(?:[^\/\n\s]+\/\S+\/|(?:v|e(?:mbed)?)\/|\S*?[?&]v=)|youtu\.be\/)([a-zA-Z0-9_-]{11})/;
    const ytMatch = url.match(ytRegex);
    if (ytMatch && ytMatch[1]) {
      return `https://www.youtube.com/embed/${ytMatch[1]}?modestbranding=1&rel=0&iv_load_policy=3&disablekb=1&controls=0&showinfo=0&enablejsapi=1&origin=${window.location.origin}`;
    }
    return url;
  };

  if (selectedCourse) {
    return (
      <div className="space-y-6 animate-in fade-in duration-500">
        <header className="flex items-center justify-between gap-4">
          <button 
            onClick={() => setSelectedCourse(null)}
            className="flex items-center gap-2 text-indigo-600 font-bold hover:text-indigo-800 transition-colors"
          >
            <ArrowLeft size={18} />
            ← Voltar para Todos os Cursos
          </button>
          {!isEditingCourse ? (
            <button 
              onClick={() => setIsEditingCourse(true)}
              className="flex items-center gap-2 bg-indigo-50 text-indigo-600 px-4 py-2 rounded-xl text-sm font-bold hover:bg-indigo-100 transition-all border border-indigo-200"
            >
              <Edit2 size={16} />
              Editar Dados do Curso
            </button>
          ) : (
            <div className="flex gap-2">
              <button 
                onClick={() => setIsEditingCourse(false)}
                className="px-4 py-2 rounded-xl text-sm font-bold text-slate-500 hover:bg-slate-100 transition-all"
              >
                Cancelar
              </button>
              <button 
                onClick={handleUpdateCourse}
                className="flex items-center gap-2 bg-indigo-600 text-white px-4 py-2 rounded-xl text-sm font-bold hover:bg-indigo-700 transition-all"
              >
                <Save size={16} />
                Salvar Alterações
              </button>
            </div>
          )}
        </header>

        {/* Informações do Curso */}
        <div className="bg-white rounded-3xl border border-slate-200 shadow-sm overflow-hidden">
          <div className="p-8 grid grid-cols-1 lg:grid-cols-3 gap-8">
            <div className="lg:col-span-1">
              <div className="relative aspect-video rounded-2xl overflow-hidden bg-slate-100 border border-slate-200 group">
                <img 
                  src={selectedCourseEdit.capaUrl || 'https://images.unsplash.com/photo-1504052434139-443c40c98408?w=800&auto=format&fit=crop&q=60'} 
                  className="w-full h-full object-cover" 
                  alt="Capa do Curso"
                />
                {isEditingCourse && (
                  <div className="absolute inset-0 bg-black/50 flex flex-col items-center justify-center p-4">
                    <label className="text-[10px] font-black text-white uppercase tracking-widest mb-2">URL da Capa</label>
                    <input 
                      className="w-full bg-white/10 border border-white/20 rounded-lg px-3 py-2 text-white text-xs outline-none focus:bg-white/20"
                      value={selectedCourseEdit.capaUrl}
                      onChange={e => setSelectedCourseEdit({...selectedCourseEdit, capaUrl: e.target.value})}
                    />
                  </div>
                )}
              </div>
            </div>
            <div className="lg:col-span-2 space-y-6">
              {isEditingCourse ? (
                <div className="space-y-4">
                  <div className="grid grid-cols-2 gap-4">
                    <div className="space-y-1.5">
                      <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Título do Curso</label>
                      <input className="w-full px-4 py-2.5 bg-slate-50 border border-slate-200 rounded-xl text-sm" value={selectedCourseEdit.nome} onChange={e => setSelectedCourseEdit({...selectedCourseEdit, nome: e.target.value})} />
                    </div>
                    <div className="space-y-1.5">
                      <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Carga Horária</label>
                      <input className="w-full px-4 py-2.5 bg-slate-50 border border-slate-200 rounded-xl text-sm" value={selectedCourseEdit.cargaHoraria} onChange={e => setSelectedCourseEdit({...selectedCourseEdit, cargaHoraria: e.target.value})} />
                    </div>
                  </div>
                  <div className="space-y-1.5">
                    <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Descrição</label>
                    <textarea rows={3} className="w-full px-4 py-2.5 bg-slate-50 border border-slate-200 rounded-xl text-sm resize-none" value={selectedCourseEdit.descricao} onChange={e => setSelectedCourseEdit({...selectedCourseEdit, descricao: e.target.value})} />
                  </div>
                </div>
              ) : (
                <div>
                  <h1 className="text-3xl font-black text-slate-900 leading-tight mb-2">{selectedCourse.nome}</h1>
                  <p className="text-slate-500 text-sm leading-relaxed mb-6">{selectedCourse.descricao || 'Nenhuma descrição fornecida.'}</p>
                  <div className="flex gap-4">
                    <div className="bg-slate-50 px-4 py-2 rounded-xl border border-slate-100">
                      <span className="text-[10px] font-bold text-slate-400 uppercase tracking-widest block">Carga Horária</span>
                      <span className="font-bold text-slate-900">{selectedCourse.cargaHoraria}</span>
                    </div>
                    <div className="bg-slate-50 px-4 py-2 rounded-xl border border-slate-100">
                      <span className="text-[10px] font-bold text-slate-400 uppercase tracking-widest block">Público</span>
                      <span className="font-bold text-slate-900">{selectedCourse.publicoAlvo}</span>
                    </div>
                  </div>
                </div>
              )}
            </div>
          </div>
        </div>

        {/* Gestão de Módulos */}
        <div className="bg-white rounded-3xl border border-slate-200 shadow-sm overflow-hidden">
          <div className="px-8 py-5 border-b border-slate-100 flex items-center justify-between bg-slate-50/50">
            <div className="flex items-center gap-3">
              <Layers size={18} className="text-indigo-600" />
              <h2 className="text-sm font-black text-slate-800 uppercase tracking-widest">Gestão de Módulos & Aulas</h2>
            </div>
            <button 
              onClick={handleCreateModule}
              className="flex items-center gap-2 bg-indigo-600 text-white px-4 py-2 rounded-xl text-xs font-bold hover:bg-indigo-700 transition-all shadow-lg shadow-indigo-100"
            >
              <Plus size={16} />
              Adicionar Novo Módulo
            </button>
          </div>

          <div className="p-8 space-y-6">
            {modules.length === 0 ? (
              <div className="py-20 text-center opacity-30">
                <Layers size={48} className="mx-auto mb-4" />
                <p className="text-sm font-bold">Nenhum módulo criado para este curso.</p>
              </div>
            ) : (
              modules.map((mod, index) => (
                <div key={mod.id} className="border border-slate-200 rounded-2xl overflow-hidden bg-slate-50/30">
                  <div className="px-6 py-4 border-b border-slate-200 bg-white flex items-center justify-between">
                    <div className="flex items-center gap-4 flex-1">
                      <span className="w-8 h-8 rounded-lg bg-slate-900 text-white flex items-center justify-center font-black text-xs">
                        {index + 1}
                      </span>
                      {editingModuleId === mod.id ? (
                        <div className="flex items-center gap-2 flex-1 max-w-sm">
                          <input 
                            autoFocus
                            className="flex-1 px-3 py-1.5 bg-slate-50 border border-slate-200 rounded-lg text-sm"
                            value={moduleEditName}
                            onChange={e => setModuleEditName(e.target.value)}
                          />
                          <button onClick={() => handleUpdateModule(mod.id)} className="p-1.5 text-emerald-600 hover:bg-emerald-50 rounded-lg"><CheckCircle size={18} /></button>
                          <button onClick={() => setEditingModuleId(null)} className="p-1.5 text-slate-400 hover:bg-slate-50 rounded-lg"><X size={18} /></button>
                        </div>
                      ) : (
                        <h3 className="font-black text-slate-800 text-base">{mod.nome}</h3>
                      )}
                    </div>
                    <div className="flex items-center gap-1">
                      <button 
                        onClick={() => handleReorderModule(mod.id, 'up')}
                        disabled={index === 0}
                        className="p-1.5 text-slate-400 hover:bg-slate-100 rounded-lg disabled:opacity-20"
                      >
                        <ChevronUp size={18} />
                      </button>
                      <button 
                        onClick={() => handleReorderModule(mod.id, 'down')}
                        disabled={index === modules.length - 1}
                        className="p-1.5 text-slate-400 hover:bg-slate-100 rounded-lg disabled:opacity-20"
                      >
                        <ChevronDown size={18} />
                      </button>
                      <button 
                        onClick={() => { setEditingModuleId(mod.id); setModuleEditName(mod.nome); }}
                        className="p-1.5 text-indigo-600 hover:bg-indigo-50 rounded-lg"
                        title="Renomear Módulo"
                      >
                        <Edit2 size={16} />
                      </button>
                      <button 
                        onClick={() => { setActiveModuleId(mod.id); setShowLessonModal(true); }}
                        className="flex items-center gap-2 bg-slate-50 text-slate-700 px-3 py-1.5 rounded-lg text-xs font-bold hover:bg-slate-100 border border-slate-200 ml-2"
                      >
                        <Plus size={14} /> Aula
                      </button>
                      <button 
                        onClick={() => handleDeleteModule(mod.id)}
                        className="p-1.5 text-red-400 hover:bg-red-50 rounded-lg ml-2"
                        title="Excluir Módulo"
                      >
                        <Trash2 size={18} />
                      </button>
                    </div>
                  </div>

                  <div className="p-4 space-y-2">
                    {lessonsByModule[mod.id]?.map((lesson) => (
                      <div key={lesson.id} className="flex items-center justify-between p-3 rounded-xl hover:bg-white hover:shadow-sm border border-transparent hover:border-slate-100 transition-all bg-transparent group/lesson">
                        <div className="flex items-center gap-4">
                          <div className="w-10 h-10 rounded-xl bg-white border border-slate-100 text-indigo-600 flex items-center justify-center shadow-sm">
                            <Play size={14} fill="currentColor" />
                          </div>
                          <div>
                            <p className="text-sm font-bold text-slate-700">{lesson.titulo}</p>
                            <div className="flex items-center gap-4 mt-1">
                              {lesson.videoUrl && <span className="text-[10px] text-slate-400 flex items-center gap-1 uppercase font-bold tracking-tighter"><Play size={10} /> Vídeo Aula</span>}
                              {lesson.materialUrl && <span className="text-[10px] text-indigo-400 flex items-center gap-1 uppercase font-bold tracking-tighter"><FileText size={10} /> Material de Apoio</span>}
