  }

  return (
    <div className="space-y-6 animate-in fade-in duration-500">
      <header className="flex flex-col sm:flex-row sm:items-center justify-between gap-4">
        <div>
          <h1 className="text-2xl font-black text-slate-900 tracking-tight">Catálogo de Cursos</h1>
          <p className="text-slate-500 text-sm font-medium">Gestão unificada de currículos e materiais pedagógicos.</p>
