              >
                <div className="relative aspect-[4/3] rounded-xl overflow-hidden mb-3 bg-slate-100 border border-slate-100">
                  <img src={course.capaUrl || 'https://images.unsplash.com/photo-1504052434139-443c40c98408?w=800&auto=format&fit=crop&q=60'} alt={course.nome} className="w-full h-full object-cover group-hover:scale-110 transition-transform duration-700" />
                  <div className="absolute top-2 right-2">
                    <span className={`px-2 py-0.5 rounded-full text-[8px] font-black uppercase ${course.status === 'ativo' ? 'bg-emerald-500 text-white shadow-lg' : 'bg-slate-700 text-white'}`}>
                      {course.status}
                    </span>
                  </div>
                </div>
                <h3 className="font-black text-slate-900 text-xs mb-1 line-clamp-2 leading-tight group-hover:text-indigo-600 transition-colors">{course.nome}</h3>
                <div className="mt-auto flex items-center justify-between text-[8px] text-slate-400 font-black uppercase tracking-widest pt-3 border-t border-slate-50">
                  <div className="flex items-center gap-1.5"><Layout size={10} className="text-slate-300" /><span>Gestão</span></div>
                  <ChevronRight size={12} className="group-hover:translate-x-1 transition-transform text-indigo-500" />
                </div>
              </div>
            ))}
          </div>
        ) : (
          <div className="flex-1 flex flex-col items-center justify-center p-16 opacity-30 text-center">
            <BookOpen size={48} className="mb-4 text-slate-300 mx-auto" />
            <h3 className="text-slate-900 font-black uppercase tracking-widest text-sm">Sem Cursos Cadastrados</h3>
            <p className="text-xs text-slate-500 font-medium">Inicie a grade acadêmica criando seu primeiro curso.</p>
          </div>
        )}
      </div>

      {/* Modal Criar Curso */}
      {showCourseModal && (
        <div className="fixed inset-0 z-[110] flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-sm animate-in fade-in duration-300">
          <div className="bg-white w-full max-w-xl rounded-3xl shadow-2xl overflow-hidden animate-in zoom-in-95 duration-200">
            <div className="p-6 border-b border-slate-100 flex items-center justify-between">
              <h3 className="font-black text-slate-900 uppercase tracking-widest text-sm">Novo Currículo EAD</h3>
              <button onClick={() => setShowCourseModal(false)} className="text-slate-400 hover:text-slate-600 p-2"><X size={20} /></button>
            </div>
            <form onSubmit={handleCreateCourse} className="p-8 space-y-6">
              <div className="space-y-4">
                <div className="space-y-1.5">
                  <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Título do Curso</label>
                  <input required autoFocus value={courseForm.nome} onChange={e => setCourseForm({...courseForm, nome: e.target.value})} placeholder="Ex: Teologia Sistemática I" className="w-full px-4 py-3 bg-slate-50 border border-slate-200 rounded-2xl text-sm" />
                </div>
                <div className="grid grid-cols-2 gap-4">
                  <div className="space-y-1.5">
                    <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Carga Horária</label>
                    <input required value={courseForm.cargaHoraria} onChange={e => setCourseForm({...courseForm, cargaHoraria: e.target.value})} placeholder="40h" className="w-full px-4 py-3 bg-slate-50 border border-slate-200 rounded-2xl text-sm" />
                  </div>
                  <div className="space-y-1.5">
                    <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Público</label>
                    <select value={courseForm.publicoAlvo} onChange={e => setCourseForm({...courseForm, publicoAlvo: e.target.value as any})} className="w-full px-4 py-3 bg-slate-50 border border-slate-200 rounded-2xl text-sm">
                      <option value="Geral">Geral</option>
                      <option value="Líderes">Líderes</option>
                      <option value="Obreiros">Obreiros</option>
                    </select>
                  </div>
                </div>
                <div className="space-y-1.5">
                  <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest">URL da Imagem de Capa</label>
                  <input value={courseForm.capaUrl} onChange={e => setCourseForm({...courseForm, capaUrl: e.target.value})} className="w-full px-4 py-3 bg-slate-50 border border-slate-200 rounded-2xl text-sm" />
                </div>
              </div>
              <button type="submit" className="w-full bg-slate-900 text-white py-4 rounded-2xl font-black text-sm uppercase tracking-widest shadow-xl shadow-slate-200">Criar Curso e Iniciar Grade</button>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

