            </div>
            <form onSubmit={handleCreateCourse} className="p-8 space-y-6">
              <input required value={courseForm.nome} onChange={e => setCourseForm({...courseForm, nome: e.target.value})} placeholder="Título do Curso" className="w-full px-4 py-3 bg-slate-50 border border-slate-200 rounded-2xl text-sm outline-none" />
              <div className="grid grid-cols-2 gap-4">
                <input required value={courseForm.cargaHoraria} onChange={e => setCourseForm({...courseForm, cargaHoraria: e.target.value})} placeholder="40h" className="w-full px-4 py-3 bg-slate-50 border border-slate-200 rounded-2xl text-sm outline-none" />
                <select value={courseForm.publicoAlvo} onChange={e => setCourseForm({...courseForm, publicoAlvo: e.target.value as any})} className="w-full px-4 py-3 bg-slate-50 border border-slate-200 rounded-2xl text-sm outline-none">
                  <option value="Geral">Geral</option>
                  <option value="Líderes">Líderes</option>
                  <option value="Obreiros">Obreiros</option>
                </select>
              </div>
              <input value={courseForm.capaUrl} onChange={e => setCourseForm({...courseForm, capaUrl: e.target.value})} placeholder="URL Imagem Capa" className="w-full px-4 py-3 bg-slate-50 border border-slate-200 rounded-2xl text-sm outline-none" />
              <button type="submit" className="w-full bg-slate-900 text-white py-4 rounded-2xl font-black text-sm uppercase tracking-widest shadow-xl shadow-slate-200">Criar Curso</button>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

export default ProfessorView;

import React, { useState, useEffect, useRef } from 'react';
import { 
  collection, 
  query, 
  where, 
  getDocs, 
  addDoc, 
  deleteDoc,
  serverTimestamp, 
  orderBy,
  doc,
  updateDoc,
  getDoc
} from 'firebase/firestore';
import { db } from '../firebase';
import { Course, Module, Lesson, User, ProfessorSubView } from '../types';
import { 
  Search, 
  BookOpen, 
  Plus, 
  X, 
  ChevronRight, 
  Play, 
  Pause,
  Volume2,
  VolumeX,
  Maximize,
  FileText, 
  ArrowLeft, 
  Layout, 
  Trash2, 
  Layers, 
  Eye, 
  Clock, 
  Download, 
  CheckCircle,
  Edit2,
  MoreVertical,
  Copy,
  ExternalLink,
  ShieldAlert
} from 'lucide-react';

interface ProfessorViewProps {
  user: User;
  activeSub: ProfessorSubView;
  onSubChange: (sub: ProfessorSubView) => void;
}

const ProfessorView: React.FC<ProfessorViewProps> = ({ user, activeSub, onSubChange }) => {
  const [myCourses, setMyCourses] = useState<Course[]>([]);
  const [loading, setLoading] = useState(true);
  const [selectedCourse, setSelectedCourse] = useState<Course | null>(null);
  const [modules, setModules] = useState<Module[]>([]);
  const [lessonsByModule, setLessonsByModule] = useState<Record<string, Lesson[]>>({});

  // Action Menu States
  const [openMenuId, setOpenMenuId] = useState<string | null>(null);
  const [duplicatingId, setDuplicatingId] = useState<string | null>(null);

  // Modal States
  const [showCourseModal, setShowCourseModal] = useState(false);
  const [showModuleModal, setShowModuleModal] = useState(false);
  const [showLessonModal, setShowLessonModal] = useState(false);
  const [activeModuleId, setActiveModuleId] = useState<string | null>(null);

  // Preview States
  const [previewLesson, setPreviewLesson] = useState<Lesson | null>(null);
  const [countdown, setCountdown] = useState(15);
  const [isTimerFinished, setIsTimerFinished] = useState(false);
  const [isConcluded, setIsConcluded] = useState(false);

  // Custom Player States
  const [playerIsPlaying, setPlayerIsPlaying] = useState(false);
  const [playerVolume, setPlayerVolume] = useState(80);
  const [isMuted, setIsMuted] = useState(false);
  const iframeRef = useRef<HTMLIFrameElement>(null);
  const playerContainerRef = useRef<HTMLDivElement>(null);

  // Form States
  const [courseForm, setCourseForm] = useState({
    nome: '',
    descricao: '',
    capaUrl: '',
    cargaHoraria: '',
    publicoAlvo: 'Geral' as const
  });
  const [moduleForm, setModuleForm] = useState({ nome: '' });
  const [lessonForm, setLessonForm] = useState({
    titulo: '',
    videoUrl: '',
    materialUrl: ''
  });

  const fetchMyCourses = async () => {
    setLoading(true);
    try {
      const q = query(collection(db, 'cursos'), where('professorId', '==', user.uid), orderBy('createdAt', 'desc'));
      const querySnapshot = await getDocs(q);
      const fetched: Course[] = [];
      querySnapshot.forEach((doc) => {
        fetched.push({ id: doc.id, ...doc.data() } as Course);
      });
      setMyCourses(fetched);
    } catch (error) {
      console.error("Erro ao carregar seus cursos:", error);
    } finally {
      setLoading(false);
    }
  };

  const fetchModules = async (courseId: string) => {
    try {
      const q = query(collection(db, 'cursos', courseId, 'modulos'), orderBy('ordem', 'asc'));
      const querySnapshot = await getDocs(q);
      const fetched: Module[] = [];
      querySnapshot.forEach((doc) => {
        fetched.push({ id: doc.id, ...doc.data() } as Module);
      });
      setModules(fetched);

      for (const mod of fetched) {
        fetchLessons(courseId, mod.id);
      }
    } catch (error) {
      console.error("Erro ao carregar módulos:", error);
    }
  };

  const fetchLessons = async (courseId: string, moduleId: string) => {
    try {
      const q = query(collection(db, 'cursos', courseId, 'modulos', moduleId, 'aulas'), orderBy('ordem', 'asc'));
      const querySnapshot = await getDocs(q);
      const fetched: Lesson[] = [];
      querySnapshot.forEach((doc) => {
        fetched.push({ id: doc.id, ...doc.data() } as Lesson);
      });
      setLessonsByModule(prev => ({ ...prev, [moduleId]: fetched }));
    } catch (error) {
      console.error("Erro ao carregar aulas:", error);
    }
  };

  useEffect(() => {
    fetchMyCourses();
  }, [user.uid]);

  useEffect(() => {
    if (activeSub === 'cursos') {
      setSelectedCourse(null);
    }
  }, [activeSub]);

  // Click outside menu listener
  useEffect(() => {
    const handleClickOutside = () => setOpenMenuId(null);
    window.addEventListener('click', handleClickOutside);
    return () => window.removeEventListener('click', handleClickOutside);
  }, []);

  // TIMER LOGIC
  useEffect(() => {
    let timer: number | undefined;
    if (previewLesson && countdown > 0 && !isConcluded) {
      timer = window.setInterval(() => {
        setCountdown((prev) => {
          if (prev <= 1) {
            setIsTimerFinished(true);
            if (timer) clearInterval(timer);
            return 0;
          }
          return prev - 1;
        });
      }, 1000);
    }
    return () => { if (timer) clearInterval(timer); };
  }, [previewLesson, countdown, isConcluded]);

  // EXCLUSÃO EM CASCATA (COURSE)
  const handleDeleteCourseFull = async (course: Course) => {
    if (!confirm(`Tem certeza? Isso apagará todos os módulos e aulas do curso "${course.nome}". Esta ação é irreversível.`)) return;

    setOpenMenuId(null);
    try {
      // 1. Localizar e limpar subcoleções (Módulos e Aulas)
      const modSnapshot = await getDocs(collection(db, 'cursos', course.id, 'modulos'));

      for (const mDoc of modSnapshot.docs) {
        // Limpa aulas de cada módulo
        const lessonSnapshot = await getDocs(collection(db, 'cursos', course.id, 'modulos', mDoc.id, 'aulas'));
        for (const lDoc of lessonSnapshot.docs) {
          await deleteDoc(doc(db, 'cursos', course.id, 'modulos', mDoc.id, 'aulas', lDoc.id));
        }
        // Remove o módulo
        await deleteDoc(doc(db, 'cursos', course.id, 'modulos', mDoc.id));
      }

      // 2. Remover o documento principal do curso
      await deleteDoc(doc(db, 'cursos', course.id));

      // 3. Resetar estado se o curso excluído for o selecionado
      if (selectedCourse?.id === course.id) {
        setSelectedCourse(null);
        onSubChange('cursos');
      }

      // 4. Atualizar lista global
      await fetchMyCourses();
      alert("Conteúdo removido com sucesso.");
    } catch (error) {
      console.error("Erro ao excluir curso:", error);
      alert("Erro: Você não tem permissão para excluir este conteúdo.");
    }
  };

  // EXCLUSÃO DE MÓDULO (COM LIMPEZA DE AULAS)
  const handleDeleteModule = async (moduleId: string) => {
    if (!selectedCourse) return;
    if (!confirm("Tem certeza que deseja excluir este módulo? Todas as aulas vinculadas serão perdidas.")) return;

    try {
      // 1. Limpa aulas do módulo antes de removê-lo
      const lessonSnapshot = await getDocs(collection(db, 'cursos', selectedCourse.id, 'modulos', moduleId, 'aulas'));
      for (const lDoc of lessonSnapshot.docs) {
        await deleteDoc(doc(db, 'cursos', selectedCourse.id, 'modulos', moduleId, 'aulas', lDoc.id));
      }

      // 2. Remove o módulo
      await deleteDoc(doc(db, 'cursos', selectedCourse.id, 'modulos', moduleId));

      // 3. Atualiza UI local
      fetchModules(selectedCourse.id);
    } catch (error) {
      console.error("Erro ao excluir módulo:", error);
      alert("Erro: Você não tem permissão para excluir este conteúdo.");
    }
  };

  // EXCLUSÃO DE AULA
  const handleDeleteLesson = async (moduleId: string, lessonId: string) => {
    if (!selectedCourse) return;
    if (!confirm("Deseja excluir esta aula permanentemente?")) return;

    try {
      await deleteDoc(doc(db, 'cursos', selectedCourse.id, 'modulos', moduleId, 'aulas', lessonId));
      fetchLessons(selectedCourse.id, moduleId);
    } catch (error) {
      console.error("Erro ao excluir aula:", error);
      alert("Erro: Você não tem permissão para excluir este conteúdo.");
    }
  };

  // DUPLICAÇÃO PROFUNDA (VALIDADO)
  const handleDuplicateCourse = async (course: Course) => {
    setDuplicatingId(course.id);
    setOpenMenuId(null);
    try {
      const newCourseRef = await addDoc(collection(db, 'cursos'), {
        ...course,
        nome: `${course.nome} (Cópia)`,
        inscritos: 0,
        createdAt: serverTimestamp(),
        status: 'rascunho'
      });

      const modSnapshot = await getDocs(query(collection(db, 'cursos', course.id, 'modulos'), orderBy('ordem', 'asc')));

      for (const mDoc of modSnapshot.docs) {
        const modData = mDoc.data();
        const newModRef = await addDoc(collection(db, 'cursos', newCourseRef.id, 'modulos'), {
          ...modData,
          createdAt: serverTimestamp()
        });

        const lessonSnapshot = await getDocs(query(collection(db, 'cursos', course.id, 'modulos', mDoc.id, 'aulas'), orderBy('ordem', 'asc')));
        for (const lDoc of lessonSnapshot.docs) {
          const lessonData = lDoc.data();
          await addDoc(collection(db, 'cursos', newCourseRef.id, 'modulos', newModRef.id, 'aulas'), {
            ...lessonData,
            createdAt: serverTimestamp()
          });
        }
      }

      await fetchMyCourses();
      alert(`Curso duplicado com sucesso!`);
    } catch (error) {
      console.error("Erro ao duplicar:", error);
      alert("Falha ao duplicar curso. Verifique sua permissão.");
    } finally {
      setDuplicatingId(null);
    }
  };

  // PLAYER COMMANDS
  const sendPlayerCommand = (func: string, args: any[] = []) => {
    if (iframeRef.current && iframeRef.current.contentWindow) {
      iframeRef.current.contentWindow.postMessage(JSON.stringify({ event: 'command', func, args }), '*');
    }
  };

  const togglePlay = () => {
    if (playerIsPlaying) sendPlayerCommand('pauseVideo');
    else sendPlayerCommand('playVideo');
    setPlayerIsPlaying(!playerIsPlaying);
  };

  const toggleMute = () => {
    if (isMuted) {
      sendPlayerCommand('unMute');
      sendPlayerCommand('setVolume', [playerVolume]);
    } else sendPlayerCommand('mute');
    setIsMuted(!isMuted);
  };

  const handleVolumeChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const vol = parseInt(e.target.value);
    setPlayerVolume(vol);
    if (!isMuted) sendPlayerCommand('setVolume', [vol]);
  };

  const toggleFullscreen = () => {
    if (playerContainerRef.current) {
      if (!document.fullscreenElement) {
        playerContainerRef.current.requestFullscreen().catch(err => console.error(err));
      } else {
        document.exitFullscreen();
      }
    }
  };

  const handleCreateCourse = async (e: React.FormEvent) => {
    e.preventDefault();
    try {
      await addDoc(collection(db, 'cursos'), {
        ...courseForm,
        professorId: user.uid,
        inscritos: 0,
        status: 'rascunho',
        createdAt: serverTimestamp()
      });
      setShowCourseModal(false);
      setCourseForm({ nome: '', descricao: '', capaUrl: '', cargaHoraria: '', publicoAlvo: 'Geral' });
      fetchMyCourses();
    } catch (error) { console.error(error); }
  };

  const handleCreateModule = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!selectedCourse) return;
    try {
      await addDoc(collection(db, 'cursos', selectedCourse.id, 'modulos'), {
        nome: moduleForm.nome,
        ordem: modules.length + 1,
        createdAt: serverTimestamp()
      });
      setShowModuleModal(false);
      setModuleForm({ nome: '' });
      fetchModules(selectedCourse.id);
    } catch (error) { console.error(error); }
  };

  const handleCreateLesson = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!selectedCourse || !activeModuleId) return;
    try {
      const currentLessonsCount = lessonsByModule[activeModuleId]?.length || 0;
      await addDoc(collection(db, 'cursos', selectedCourse.id, 'modulos', activeModuleId, 'aulas'), {
        ...lessonForm,
        ordem: currentLessonsCount + 1,
        createdAt: serverTimestamp()
      });
      setShowLessonModal(false);
      setLessonForm({ titulo: '', videoUrl: '', materialUrl: '' });
      fetchLessons(selectedCourse.id, activeModuleId);
    } catch (error) { console.error(error); }
  };

  const handleManageCourse = (course: Course) => {
    setSelectedCourse(course);
    onSubChange('modulos');
    fetchModules(course.id);
  };

  const openPreview = (lesson: Lesson) => {
    setCountdown(15);
    setIsTimerFinished(false);
    setIsConcluded(false);
    setPlayerIsPlaying(false);
    setPreviewLesson(lesson);
  };

  const closePreview = () => {
    setPreviewLesson(null);
    setIsTimerFinished(false);
    setIsConcluded(false);
    setCountdown(15);
    setPlayerIsPlaying(false);
  };

  const handleConcludeLesson = () => {
    if (!isTimerFinished) return;
    setIsConcluded(true);
  };

  const getEmbedUrl = (url: string) => {
    if (!url) return "";
    const ytRegex = /(?:https?:\/\/)?(?:www\.)?(?:youtube\.com\/(?:[^\/\n\s]+\/\S+\/|(?:v|e(?:mbed)?)\/|\S*?[?&]v=)|youtu\.be\/)([a-zA-Z0-9_-]{11})/;
    const ytMatch = url.match(ytRegex);
    if (ytMatch && ytMatch[1]) {
      return `https://www.youtube.com/embed/${ytMatch[1]}?modestbranding=1&rel=0&iv_load_policy=3&disablekb=1&controls=0&showinfo=0&enablejsapi=1&origin=${window.location.origin}`;
    }
    return url;
  };

  // Componente de Dropdown de Ações
  const ActionMenu = ({ course }: { course: Course }) => (
    <div className="relative" onClick={e => e.stopPropagation()}>
      <button 
        onClick={() => setOpenMenuId(openMenuId === course.id ? null : course.id)}
        className="p-2 text-slate-400 hover:text-slate-900 transition-colors rounded-lg hover:bg-slate-100"
      >
        <MoreVertical size={16} />
      </button>

      {openMenuId === course.id && (
        <div className="absolute right-0 top-full mt-2 w-48 bg-white border border-slate-200 rounded-xl shadow-2xl z-[150] overflow-hidden animate-in fade-in slide-in-from-top-2 duration-200">
          <button 
            onClick={() => handleManageCourse(course)}
            className="w-full flex items-center gap-3 px-4 py-2.5 text-xs font-bold text-slate-700 hover:bg-indigo-50 hover:text-indigo-600 transition-all text-left"
          >
            <Edit2 size={14} /> Editar Grade
          </button>
          <button 
            onClick={() => handleDuplicateCourse(course)}
            className="w-full flex items-center gap-3 px-4 py-2.5 text-xs font-bold text-slate-700 hover:bg-indigo-50 hover:text-indigo-600 transition-all text-left"
          >
            <Copy size={14} /> Duplicar Curso
          </button>
          <button 
            onClick={() => { setSelectedCourse(course); }}
            className="w-full flex items-center gap-3 px-4 py-2.5 text-xs font-bold text-slate-700 hover:bg-indigo-50 hover:text-indigo-600 transition-all text-left"
          >
            <ExternalLink size={14} /> Ver como Aluno
          </button>
          <div className="border-t border-slate-100 my-1"></div>
          <button 
            onClick={() => handleDeleteCourseFull(course)}
            className="w-full flex items-center gap-3 px-4 py-2.5 text-xs font-bold text-red-500 hover:bg-red-50 transition-all text-left"
          >
            <Trash2 size={14} /> Excluir Curso
          </button>
        </div>
      )}
    </div>
  );

  // RENDER: GESTÃO DO CURSO (Módulos & Aulas)
  if (activeSub === 'modulos' && selectedCourse) {
    return (
      <div className="space-y-6 animate-in fade-in duration-500">
        <header className="flex items-center justify-between gap-4">
          <div className="flex items-center gap-4">
            <button 
              onClick={() => onSubChange('cursos')}
              className="flex items-center justify-center h-10 w-10 bg-white border border-slate-200 hover:bg-slate-50 rounded-xl text-slate-600 transition-all shadow-sm group"
            >
              <ArrowLeft size={20} className="group-hover:-translate-x-1 transition-transform" />
            </button>
            <div>
              <h1 className="text-2xl font-bold text-slate-900 leading-tight">{selectedCourse.nome}</h1>
              <div className="flex items-center gap-2 mt-0.5">
                <span className="text-slate-400 text-xs font-medium uppercase tracking-wider">Gestão de Conteúdo</span>
                <span className="h-1 w-1 rounded-full bg-slate-300"></span>
                <span className="text-indigo-600 text-xs font-bold uppercase tracking-wider">{selectedCourse.publicoAlvo}</span>
              </div>
            </div>
          </div>
          <button 
            onClick={() => setShowModuleModal(true)}
            className="flex items-center gap-2 bg-indigo-600 text-white px-5 py-2.5 rounded-xl text-sm font-bold hover:bg-indigo-700 transition-all shadow-lg shadow-indigo-200/20"
          >
            <Plus size={18} />
            Novo Módulo
          </button>
        </header>

        <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
          <div className="lg:col-span-2 space-y-4">
            <div className="bg-white rounded-2xl border border-slate-200 shadow-sm overflow-hidden">
              <div className="px-6 py-4 border-b border-slate-100 flex items-center justify-between bg-slate-50/50">
                <div className="flex items-center gap-2">
                  <Layout size={16} className="text-slate-400" />
                  <h2 className="text-xs font-bold text-slate-800 uppercase tracking-widest">Matriz Curricular</h2>
                </div>
                <span className="text-[10px] font-bold text-slate-400">{modules.length} Módulos</span>
              </div>

              <div className="p-4 space-y-4">
                {modules.length === 0 ? (
                  <div className="p-16 text-center opacity-40">
                    <Layers size={32} className="mx-auto mb-2 text-slate-300" />
                    <p className="text-sm font-medium">Nenhum módulo criado.</p>
                  </div>
                ) : (
                  modules.map((mod) => (
                    <div key={mod.id} className="border border-slate-100 rounded-xl overflow-hidden bg-slate-50/30 group">
                      <div className="px-4 py-3 border-b border-slate-100 flex items-center justify-between bg-white group-hover:bg-slate-50 transition-colors">
                        <div className="flex items-center gap-3">
                          <span className="bg-slate-900 text-white w-6 h-6 rounded-lg flex items-center justify-center text-[10px] font-black">{mod.ordem}</span>
                          <h3 className="font-bold text-slate-800 text-sm">{mod.nome}</h3>
                        </div>
                        <div className="flex items-center gap-1 opacity-0 group-hover:opacity-100 transition-opacity">
                          <button onClick={() => { setActiveModuleId(mod.id); setShowLessonModal(true); }} className="p-1.5 text-indigo-600 hover:bg-indigo-50 rounded-lg" title="Adicionar Aula"><Plus size={18} /></button>
                          <button onClick={() => handleDeleteModule(mod.id)} className="p-1.5 text-red-500 hover:bg-red-50 rounded-lg" title="Excluir Módulo"><Trash2 size={18} /></button>
                        </div>
                      </div>

                      <div className="p-2 space-y-1">
                        {lessonsByModule[mod.id]?.map((lesson) => (
                          <div key={lesson.id} className="flex items-center justify-between p-3 rounded-xl hover:bg-white hover:shadow-sm transition-all group/lesson bg-transparent">
                            <div className="flex items-center gap-4">
                              <div className="p-2 bg-white border border-slate-100 text-indigo-600 rounded-lg shadow-sm"><Play size={12} fill="currentColor" /></div>
                              <p className="text-sm font-semibold text-slate-700">{lesson.titulo}</p>
                            </div>
                            <div className="flex items-center gap-1 opacity-0 group-hover/lesson:opacity-100 transition-all">
                              <button onClick={() => openPreview(lesson)} className="p-1.5 text-indigo-600 hover:bg-indigo-50 rounded-lg"><Eye size={16} /></button>
                              <button onClick={() => handleDeleteLesson(mod.id, lesson.id)} className="p-1.5 text-slate-300 hover:text-red-500 transition-all"><Trash2 size={14} /></button>
                            </div>
                          </div>
                        ))}
                      </div>
                    </div>
                  ))
                )}
              </div>
            </div>
          </div>

          <div className="space-y-4">
            <div className="bg-white p-5 rounded-2xl border border-slate-200 shadow-sm sticky top-24">
              <img src={selectedCourse.capaUrl} className="w-full h-32 object-cover rounded-xl mb-4 border border-slate-100" />
              <div className="space-y-3">
                <div className="flex justify-between text-xs border-b border-slate-50 pb-2">
                   <span className="text-slate-400 font-bold uppercase">Inscritos</span>
                   <span className="font-black text-slate-900">{selectedCourse.inscritos} Alunos</span>
                </div>
                <div className="flex justify-between text-xs border-b border-slate-50 pb-2">
                   <span className="text-slate-400 font-bold uppercase">Carga Horária</span>
                   <span className="font-black text-slate-900">{selectedCourse.cargaHoraria}</span>
                </div>
              </div>
            </div>
          </div>
        </div>

        {/* MODAIS */}
        {showModuleModal && (
          <div className="fixed inset-0 z-[110] flex items-center justify-center p-4 bg-slate-900/40 backdrop-blur-sm">
            <div className="bg-white w-full max-w-md rounded-2xl shadow-2xl overflow-hidden">
              <div className="p-4 border-b border-slate-100 flex items-center justify-between">
                <h3 className="font-bold text-slate-900">Novo Módulo Acadêmico</h3>
                <button onClick={() => setShowModuleModal(false)} className="text-slate-400 hover:text-slate-600"><X size={20} /></button>
              </div>
              <form onSubmit={handleCreateModule} className="p-6 space-y-4">
                <input required autoFocus value={moduleForm.nome} onChange={e => setModuleForm({nome: e.target.value})} placeholder="Título do Módulo" className="w-full px-4 py-2.5 bg-slate-50 border border-slate-200 rounded-xl text-sm outline-none" />
                <button type="submit" className="w-full bg-indigo-600 text-white py-2.5 rounded-xl font-bold text-sm">Criar Módulo</button>
              </form>
            </div>
          </div>
        )}

        {showLessonModal && (
          <div className="fixed inset-0 z-[110] flex items-center justify-center p-4 bg-slate-900/40 backdrop-blur-sm">
            <div className="bg-white w-full max-w-lg rounded-2xl shadow-2xl overflow-hidden">
              <div className="p-4 border-b border-slate-100 flex items-center justify-between">
                <h3 className="font-bold text-slate-900">Adicionar Aula</h3>
                <button onClick={() => setShowLessonModal(false)} className="text-slate-400 hover:text-slate-600"><X size={20} /></button>
              </div>
              <form onSubmit={handleCreateLesson} className="p-6 space-y-4">
                <input required autoFocus value={lessonForm.titulo} onChange={e => setLessonForm({...lessonForm, titulo: e.target.value})} placeholder="Título da Aula" className="w-full px-4 py-2.5 bg-slate-50 border border-slate-200 rounded-xl text-sm" />
                <input value={lessonForm.videoUrl} onChange={e => setLessonForm({...lessonForm, videoUrl: e.target.value})} placeholder="Link Vídeo (YouTube)" className="w-full px-4 py-2 bg-slate-50 border border-slate-200 rounded-xl text-sm" />
                <input value={lessonForm.materialUrl} onChange={e => setLessonForm({...lessonForm, materialUrl: e.target.value})} placeholder="Link Material (PDF)" className="w-full px-4 py-2 bg-slate-50 border border-slate-200 rounded-xl text-sm" />
                <button type="submit" className="w-full bg-indigo-600 text-white py-3 rounded-xl font-bold text-sm">Publicar Aula</button>
              </form>
            </div>
          </div>
        )}

        {/* PLAYER MODAL (PRESERVADO) */}
        {previewLesson && (
          <div className="fixed inset-0 z-[200] flex items-center justify-center p-4 bg-slate-900/80 backdrop-blur-md">
            <div className="bg-white w-full max-w-6xl h-[90vh] rounded-3xl shadow-2xl overflow-hidden flex flex-col animate-in zoom-in-95 duration-200">
              <div className="p-5 border-b border-slate-100 flex items-center justify-between bg-white">
                <div className="flex items-center gap-3">
                  <div className="bg-indigo-600 p-2 rounded-xl text-white shadow-lg shadow-indigo-200"><Eye size={18} /></div>
                  <h3 className="font-bold text-slate-900 text-base leading-tight">Pré-visualização de Aula: {previewLesson.titulo}</h3>
                </div>
                <button onClick={closePreview} className="flex items-center gap-2 px-4 py-2 bg-slate-100 hover:bg-slate-200 rounded-xl text-slate-600 text-xs font-bold transition-colors">
                  <X size={16} /> Fechar Aula
                </button>
              </div>
              <div className="flex-1 overflow-y-auto bg-slate-50/50 p-6 flex flex-col lg:flex-row gap-6">
                <div className="flex-[2] flex flex-col justify-center">
                  <div ref={playerContainerRef} className="aspect-video bg-slate-900 rounded-2xl overflow-hidden shadow-2xl border-4 border-white relative group">
                    <iframe ref={iframeRef} width="100%" height="100%" src={getEmbedUrl(previewLesson.videoUrl)} title="Video Player" frameBorder="0" allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture" allowFullScreen className="pointer-events-none"></iframe>
                    <div className="absolute inset-0 z-20 pointer-events-none flex flex-col justify-end">
                      {!playerIsPlaying && (
                        <div className="absolute inset-0 flex items-center justify-center bg-black/20 backdrop-blur-[2px] pointer-events-auto cursor-pointer" onClick={togglePlay}>
                          <div className="w-20 h-20 bg-white/10 backdrop-blur-xl border border-white/20 rounded-full flex items-center justify-center text-white scale-100 group-hover:scale-110 transition-all shadow-2xl"><Play size={40} fill="currentColor" /></div>
                        </div>
                      )}
                      <div className="p-4 bg-gradient-to-t from-black/80 to-transparent opacity-0 group-hover:opacity-100 transition-opacity duration-300 pointer-events-auto flex items-center justify-between px-8">
                        <div className="flex items-center gap-4">
                          <button onClick={togglePlay} className="text-white hover:text-indigo-400 transition-colors">
                            {playerIsPlaying ? <Pause size={24} fill="currentColor" /> : <Play size={24} fill="currentColor" />}
                          </button>
                          <div className="flex items-center gap-3 group/vol">
                            <button onClick={toggleMute} className="text-white hover:text-indigo-400">
                              {(isMuted || playerVolume === 0) ? <VolumeX size={20} /> : <Volume2 size={20} />}
                            </button>
                            <input type="range" min="0" max="100" value={isMuted ? 0 : playerVolume} onChange={handleVolumeChange} className="w-20 h-1.5 bg-white/20 rounded-full appearance-none cursor-pointer accent-indigo-500" />
                          </div>
                        </div>
                        <button onClick={toggleFullscreen} className="text-white hover:text-indigo-400 transition-colors"><Maximize size={20} /></button>
                      </div>
                    </div>
                  </div>
                </div>
                <div className="flex-1 space-y-4">
                   <div className="bg-white p-6 rounded-2xl border border-slate-200 shadow-sm sticky top-0">
                      <h4 className="text-xs font-black text-slate-400 uppercase tracking-[0.2em] mb-4">Métrica Pedagógica</h4>
                      <div className="space-y-4">
                         <div className="bg-slate-50 p-6 rounded-xl text-center border border-slate-100">
                           {!isTimerFinished ? (
                             <div className="space-y-2"><span className="text-4xl font-black text-slate-900 tracking-tighter">{countdown}s</span><p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">Tempo para Validação</p></div>
                           ) : (
                             <div className="py-2 text-emerald-600 font-bold uppercase text-xs">Validado</div>
                           )}
                         </div>
                         <button disabled={!isTimerFinished || isConcluded} onClick={handleConcludeLesson} className={`w-full py-4 rounded-xl font-bold text-sm shadow-lg ${isTimerFinished && !isConcluded ? 'bg-slate-900 text-white' : isConcluded ? 'bg-emerald-100 text-emerald-700' : 'bg-slate-100 text-slate-400'}`}>
                           {isConcluded ? 'Aula Concluída' : 'Validar Presença'}
                         </button>
                         {isConcluded && previewLesson.materialUrl && (
                           <a href={previewLesson.materialUrl} target="_blank" rel="noopener noreferrer" className="w-full py-4 bg-indigo-600 text-white rounded-xl font-bold text-sm shadow-lg flex items-center justify-center gap-2 hover:bg-indigo-700 transition-all">
                             <Download size={18} /> 📥 Baixar Material
                           </a>
                         )}
                      </div>
                   </div>
                </div>
              </div>
            </div>
          </div>
        )}
      </div>
    );
  }

  // RENDER: LISTA DE CURSOS (Tab: Módulos)
  if (activeSub === 'modulos' && !selectedCourse) {
    return (
      <div className="space-y-6 animate-in fade-in duration-500">
        <header>
          <h1 className="text-2xl font-black text-slate-900 tracking-tight uppercase">Módulos Acadêmicos</h1>
          <p className="text-slate-500 text-sm font-medium">Gestão detalhada da matriz curricular por disciplina.</p>
        </header>

        <div className="bg-white rounded-2xl border border-slate-200 shadow-sm overflow-hidden">
          <table className="w-full text-left">
             <thead className="bg-slate-50 text-[10px] uppercase font-bold text-slate-400 tracking-widest border-b border-slate-100">
               <tr>
                 <th className="px-6 py-4">Curso / Disciplina</th>
                 <th className="px-6 py-4">Público</th>
                 <th className="px-6 py-4">Alunos</th>
                 <th className="px-6 py-4 text-right">Ações</th>
               </tr>
             </thead>
             <tbody className="divide-y divide-slate-100">
               {loading ? (
                 <tr><td colSpan={4} className="p-12 text-center text-slate-400 text-xs italic">Sincronizando banco de dados...</td></tr>
               ) : myCourses.map(course => (
                 <tr key={course.id} className="hover:bg-slate-50 transition-all group">
                   <td className="px-6 py-4">
                     <div className="flex items-center gap-3">
                       <img src={course.capaUrl} className="w-10 h-10 rounded-lg object-cover border border-slate-100" />
                       <span className="font-bold text-slate-800 text-sm">{course.nome}</span>
                     </div>
                   </td>
                   <td className="px-6 py-4 text-xs font-bold text-indigo-600 uppercase tracking-tighter">{course.publicoAlvo}</td>
                   <td className="px-6 py-4 text-xs text-slate-500 font-medium">{course.inscritos} Alunos</td>
                   <td className="px-6 py-4 text-right flex items-center justify-end gap-2">
                     <button onClick={() => handleManageCourse(course)} className="flex items-center gap-1.5 bg-indigo-600 text-white px-4 py-1.5 rounded-lg text-[10px] font-black uppercase tracking-widest hover:bg-indigo-700 transition-all shadow-lg shadow-indigo-100">
                       <Edit2 size={12} /> Gerenciar Módulos
                     </button>
                     <ActionMenu course={course} />
                   </td>
                 </tr>
               ))}
             </tbody>
          </table>
        </div>
      </div>
    );
  }

  // RENDER: GRID DE CURSOS (Tab: Cursos)
  return (
    <div className="space-y-6 animate-in fade-in duration-500">
      <header className="flex flex-col sm:flex-row sm:items-center justify-between gap-4">
        <div>
          <h1 className="text-2xl font-black text-slate-900 tracking-tight uppercase">Catálogo Global</h1>
          <p className="text-slate-500 text-sm font-medium">Gerencie currículos, duplique treinamentos ou remova conteúdos.</p>
        </div>
        <button onClick={() => setShowCourseModal(true)} className="flex items-center justify-center gap-2 bg-indigo-600 text-white px-6 py-3 rounded-2xl text-sm font-black hover:bg-indigo-700 transition-all shadow-xl shadow-indigo-100 uppercase tracking-widest">
          <Plus size={18} /> Cadastrar Novo
        </button>
      </header>

      <div className="bg-white rounded-3xl border border-slate-200 shadow-sm min-h-[400px] flex flex-col overflow-hidden">
        <div className="p-5 border-b border-slate-100 flex flex-col sm:flex-row items-center justify-between gap-4 bg-slate-50/30">
          <div className="relative w-full max-w-xs">
            <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={16} />
            <input type="text" placeholder="Localizar curso..." className="w-full pl-10 pr-4 py-2.5 bg-white border border-slate-200 rounded-xl text-xs outline-none shadow-sm font-medium" />
          </div>
        </div>

        {loading ? (
          <div className="flex-1 flex items-center justify-center p-12"><div className="h-6 w-6 animate-spin rounded-full border-2 border-indigo-600 border-t-transparent"></div></div>
        ) : myCourses.length > 0 ? (
          <div className="grid grid-cols-1 sm:grid-cols-2 md:grid-cols-3 lg:grid-cols-4 xl:grid-cols-6 gap-6 p-8">
            {myCourses.map(course => (
              <div 
                key={course.id} 
                className="border border-slate-200 p-3 rounded-3xl hover:shadow-xl hover:border-indigo-400 transition-all bg-white flex flex-col relative overflow-hidden group/card"
              >
                {duplicatingId === course.id && (
                  <div className="absolute inset-0 z-10 bg-white/80 backdrop-blur-sm flex flex-col items-center justify-center gap-2">
                    <div className="h-6 w-6 animate-spin rounded-full border-2 border-indigo-600 border-t-transparent"></div>
                    <span className="text-[9px] font-black uppercase text-indigo-600">Sincronizando...</span>
                  </div>
                )}

                <div className="relative aspect-[4/3] rounded-2xl overflow-hidden mb-3 bg-slate-100 border border-slate-100">
                  <img src={course.capaUrl} className="w-full h-full object-cover group-hover/card:scale-110 transition-transform duration-700" />
                  <div className="absolute top-2 right-2 flex gap-1">
                    <ActionMenu course={course} />
                  </div>
                </div>
                <h3 className="font-black text-slate-900 text-[11px] mb-1 line-clamp-2 leading-tight uppercase group-hover/card:text-indigo-600 transition-colors">{course.nome}</h3>

                <div 
                  onClick={() => handleManageCourse(course)} 
                  className="mt-auto flex items-center justify-between text-[8px] text-slate-400 font-black uppercase tracking-widest pt-3 border-t border-slate-50 cursor-pointer"
                >
                  <div className="flex items-center gap-1.5"><Layout size={10} className="text-slate-300" /><span>Gerenciar</span></div>
                  <ChevronRight size={12} className="group-hover/card:translate-x-1 transition-transform text-indigo-500" />
                </div>
              </div>
            ))}
          </div>
        ) : (
          <div className="flex-1 flex flex-col items-center justify-center p-16 opacity-30 text-center">
            <BookOpen size={48} className="mb-4 text-slate-300 mx-auto" />
            <h3 className="text-slate-900 font-black uppercase tracking-widest text-sm">Nenhum curso cadastrado</h3>
          </div>
        )}
      </div>

      {/* MODAL CRIAR CURSO */}
      {showCourseModal && (
        <div className="fixed inset-0 z-[110] flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-sm">
          <div className="bg-white w-full max-w-xl rounded-3xl shadow-2xl overflow-hidden animate-in zoom-in-95">
            <div className="p-6 border-b border-slate-100 flex items-center justify-between">
              <h3 className="font-black text-slate-900 uppercase tracking-widest text-sm">Novo Currículo</h3>
              <button onClick={() => setShowCourseModal(false)} className="text-slate-400 hover:text-slate-600"><X size={20} /></button>
            </div>
            <form onSubmit={handleCreateCourse} className="p-8 space-y-6">
              <input required value={courseForm.nome} onChange={e => setCourseForm({...courseForm, nome: e.target.value})} placeholder="Título do Curso" className="w-full px-4 py-3 bg-slate-50 border border-slate-200 rounded-2xl text-sm outline-none" />
              <div className="grid grid-cols-2 gap-4">
                <input required value={courseForm.cargaHoraria} onChange={e => setCourseForm({...courseForm, cargaHoraria: e.target.value})} placeholder="Ex: 40h" className="w-full px-4 py-3 bg-slate-50 border border-slate-200 rounded-2xl text-sm outline-none" />
                <select value={courseForm.publicoAlvo} onChange={e => setCourseForm({...courseForm, publicoAlvo: e.target.value as any})} className="w-full px-4 py-3 bg-slate-50 border border-slate-200 rounded-2xl text-sm outline-none">
                  <option value="Geral">Geral</option>
                  <option value="Líderes">Líderes</option>
                  <option value="Obreiros">Obreiros</option>
                </select>
              </div>
              <input value={courseForm.capaUrl} onChange={e => setCourseForm({...courseForm, capaUrl: e.target.value})} placeholder="URL Imagem Capa" className="w-full px-4 py-3 bg-slate-50 border border-slate-200 rounded-2xl text-sm outline-none" />
              <button type="submit" className="w-full bg-slate-900 text-white py-4 rounded-2xl font-black text-sm uppercase tracking-widest shadow-xl shadow-slate-200">Criar Curso</button>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

export default ProfessorView;

import React, { useState, useEffect, useRef } from 'react';
import { 
  collection, 
  query, 
  where, 
  getDocs, 
  addDoc, 
  deleteDoc,
  serverTimestamp, 
  orderBy,
  doc,
  updateDoc,
  getDoc
} from 'firebase/firestore';
import { db } from '../firebase';
import { Course, Module, Lesson, User, ProfessorSubView } from '../types';
import { 
  Search, 
  BookOpen, 
  Plus, 
  X, 
  ChevronRight, 
  Play, 
  Pause,
  Volume2,
  VolumeX,
  Maximize,
  FileText, 
  ArrowLeft, 
  Layout, 
  Trash2, 
  Layers, 
  Eye, 
  Clock, 
  Download, 
  CheckCircle,
  Edit2,
  MoreVertical,
  Copy,
  ExternalLink,
  ShieldAlert
} from 'lucide-react';

interface ProfessorViewProps {
  user: User;
  activeSub: ProfessorSubView;
  onSubChange: (sub: ProfessorSubView) => void;
}

const ProfessorView: React.FC<ProfessorViewProps> = ({ user, activeSub, onSubChange }) => {
  const [myCourses, setMyCourses] = useState<Course[]>([]);
  const [loading, setLoading] = useState(true);
  const [selectedCourse, setSelectedCourse] = useState<Course | null>(null);
  const [modules, setModules] = useState<Module[]>([]);
  const [lessonsByModule, setLessonsByModule] = useState<Record<string, Lesson[]>>({});

  // Action Menu States
  const [openMenuId, setOpenMenuId] = useState<string | null>(null);
  const [duplicatingId, setDuplicatingId] = useState<string | null>(null);

  // Modal States
  const [showCourseModal, setShowCourseModal] = useState(false);
  const [showModuleModal, setShowModuleModal] = useState(false);
  const [showLessonModal, setShowLessonModal] = useState(false);
  const [activeModuleId, setActiveModuleId] = useState<string | null>(null);

  // Preview States
  const [previewLesson, setPreviewLesson] = useState<Lesson | null>(null);
  const [countdown, setCountdown] = useState(15);
  const [isTimerFinished, setIsTimerFinished] = useState(false);
  const [isConcluded, setIsConcluded] = useState(false);

  // Custom Player States
  const [playerIsPlaying, setPlayerIsPlaying] = useState(false);
  const [playerVolume, setPlayerVolume] = useState(80);
  const [isMuted, setIsMuted] = useState(false);
  const iframeRef = useRef<HTMLIFrameElement>(null);
  const playerContainerRef = useRef<HTMLDivElement>(null);

  // Form States
  const [courseForm, setCourseForm] = useState({
    nome: '',
    descricao: '',
    capaUrl: '',
    cargaHoraria: '',
    publicoAlvo: 'Geral' as const
  });
  const [moduleForm, setModuleForm] = useState({ nome: '' });
  const [lessonForm, setLessonForm] = useState({
    titulo: '',
    videoUrl: '',
    materialUrl: ''
  });

  const fetchMyCourses = async () => {
    setLoading(true);
    try {
      const q = query(collection(db, 'cursos'), where('professorId', '==', user.uid), orderBy('createdAt', 'desc'));
      const querySnapshot = await getDocs(q);
      const fetched: Course[] = [];
      querySnapshot.forEach((doc) => {
        fetched.push({ id: doc.id, ...doc.data() } as Course);
      });
      setMyCourses(fetched);
    } catch (error) {
      console.error("Erro ao carregar seus cursos:", error);
    } finally {
      setLoading(false);
    }
  };

  const fetchModules = async (courseId: string) => {
    try {
      const q = query(collection(db, 'cursos', courseId, 'modulos'), orderBy('ordem', 'asc'));
      const querySnapshot = await getDocs(q);
      const fetched: Module[] = [];
      querySnapshot.forEach((doc) => {
        fetched.push({ id: doc.id, ...doc.data() } as Module);
      });
      setModules(fetched);

      for (const mod of fetched) {
        fetchLessons(courseId, mod.id);
      }
    } catch (error) {
      console.error("Erro ao carregar módulos:", error);
    }
  };

  const fetchLessons = async (courseId: string, moduleId: string) => {
    try {
      const q = query(collection(db, 'cursos', courseId, 'modulos', moduleId, 'aulas'), orderBy('ordem', 'asc'));
      const querySnapshot = await getDocs(q);
      const fetched: Lesson[] = [];
      querySnapshot.forEach((doc) => {
        fetched.push({ id: doc.id, ...doc.data() } as Lesson);
      });
      setLessonsByModule(prev => ({ ...prev, [moduleId]: fetched }));
    } catch (error) {
      console.error("Erro ao carregar aulas:", error);
    }
  };

  useEffect(() => {
    fetchMyCourses();
  }, [user.uid]);

  useEffect(() => {
    if (activeSub === 'cursos') {
      setSelectedCourse(null);
    }
  }, [activeSub]);

  // Click outside menu listener
  useEffect(() => {
    const handleClickOutside = (e: MouseEvent) => {
       if (!(e.target as HTMLElement).closest('.action-menu-container')) {
         setOpenMenuId(null);
       }
    };
    window.addEventListener('click', handleClickOutside);
    return () => window.removeEventListener('click', handleClickOutside);
  }, []);

  // EXCLUSÃO EM CASCATA (COURSE)
  const handleDeleteCourseFull = async (course: Course) => {
    if (!confirm(`Tem certeza? Isso apagará todos os módulos e aulas do curso "${course.nome}". Esta ação é irreversível.`)) return;

    setOpenMenuId(null);
    try {
      const modSnapshot = await getDocs(collection(db, 'cursos', course.id, 'modulos'));

      for (const mDoc of modSnapshot.docs) {
        const lessonSnapshot = await getDocs(collection(db, 'cursos', course.id, 'modulos', mDoc.id, 'aulas'));
        for (const lDoc of lessonSnapshot.docs) {
          await deleteDoc(doc(db, 'cursos', course.id, 'modulos', mDoc.id, 'aulas', lDoc.id));
        }
        await deleteDoc(doc(db, 'cursos', course.id, 'modulos', mDoc.id));
      }

      await deleteDoc(doc(db, 'cursos', course.id));

      if (selectedCourse?.id === course.id) {
        setSelectedCourse(null);
        onSubChange('cursos');
      }

      await fetchMyCourses();
      alert("Conteúdo removido com sucesso.");
    } catch (error) {
      console.error("Erro ao excluir curso:", error);
      alert("Erro: Você não tem permissão para excluir este conteúdo.");
    }
  };

  // EXCLUSÃO DE MÓDULO (COM LIMPEZA DE AULAS)
  const handleDeleteModule = async (moduleId: string) => {
    if (!selectedCourse) return;
    if (!confirm("Tem certeza que deseja excluir este módulo? Todas as aulas vinculadas serão perdidas.")) return;

    try {
      const lessonSnapshot = await getDocs(collection(db, 'cursos', selectedCourse.id, 'modulos', moduleId, 'aulas'));
      for (const lDoc of lessonSnapshot.docs) {
        await deleteDoc(doc(db, 'cursos', selectedCourse.id, 'modulos', moduleId, 'aulas', lDoc.id));
      }

      await deleteDoc(doc(db, 'cursos', selectedCourse.id, 'modulos', moduleId));
      fetchModules(selectedCourse.id);
    } catch (error) {
      console.error("Erro ao excluir módulo:", error);
      alert("Erro: Você não tem permissão para excluir este conteúdo.");
    }
  };

  // EXCLUSÃO DE AULA
  const handleDeleteLesson = async (moduleId: string, lessonId: string) => {
    if (!selectedCourse) return;
    if (!confirm("Deseja excluir esta aula permanentemente?")) return;

    try {
      await deleteDoc(doc(db, 'cursos', selectedCourse.id, 'modulos', moduleId, 'aulas', lessonId));
      fetchLessons(selectedCourse.id, moduleId);
    } catch (error) {
      console.error("Erro ao excluir aula:", error);
      alert("Erro: Você não tem permissão para excluir este conteúdo.");
    }
  };

  // DUPLICAÇÃO PROFUNDA
  const handleDuplicateCourse = async (course: Course) => {
    setDuplicatingId(course.id);
    setOpenMenuId(null);
    try {
      const newCourseRef = await addDoc(collection(db, 'cursos'), {
        ...course,
        nome: `${course.nome} (Cópia)`,
        inscritos: 0,
        createdAt: serverTimestamp(),
        status: 'rascunho'
      });

      const modSnapshot = await getDocs(query(collection(db, 'cursos', course.id, 'modulos'), orderBy('ordem', 'asc')));

      for (const mDoc of modSnapshot.docs) {
        const modData = mDoc.data();
        const newModRef = await addDoc(collection(db, 'cursos', newCourseRef.id, 'modulos'), {
          ...modData,
          createdAt: serverTimestamp()
        });

        const lessonSnapshot = await getDocs(query(collection(db, 'cursos', course.id, 'modulos', mDoc.id, 'aulas'), orderBy('ordem', 'asc')));
        for (const lDoc of lessonSnapshot.docs) {
          const lessonData = lDoc.data();
          await addDoc(collection(db, 'cursos', newCourseRef.id, 'modulos', newModRef.id, 'aulas'), {
            ...lessonData,
            createdAt: serverTimestamp()
          });
        }
      }

      await fetchMyCourses();
      alert(`Curso duplicado com sucesso!`);
    } catch (error) {
      console.error("Erro ao duplicar:", error);
      alert("Falha ao duplicar curso. Verifique sua permissão.");
    } finally {
      setDuplicatingId(null);
    }
  };

  // PLAYER COMMANDS
  const sendPlayerCommand = (func: string, args: any[] = []) => {
    if (iframeRef.current && iframeRef.current.contentWindow) {
      iframeRef.current.contentWindow.postMessage(JSON.stringify({ event: 'command', func, args }), '*');
    }
  };

  const togglePlay = () => {
    if (playerIsPlaying) sendPlayerCommand('pauseVideo');
    else sendPlayerCommand('playVideo');
    setPlayerIsPlaying(!playerIsPlaying);
  };

  const toggleMute = () => {
    if (isMuted) {
      sendPlayerCommand('unMute');
      sendPlayerCommand('setVolume', [playerVolume]);
    } else sendPlayerCommand('mute');
    setIsMuted(!isMuted);
  };

  const handleVolumeChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const vol = parseInt(e.target.value);
    setPlayerVolume(vol);
    if (!isMuted) sendPlayerCommand('setVolume', [vol]);
  };

  const toggleFullscreen = () => {
    if (playerContainerRef.current) {
      if (!document.fullscreenElement) {
        playerContainerRef.current.requestFullscreen().catch(err => console.error(err));
      } else {
        document.exitFullscreen();
      }
    }
  };

  const handleCreateCourse = async (e: React.FormEvent) => {
    e.preventDefault();
    try {
      await addDoc(collection(db, 'cursos'), {
        ...courseForm,
        professorId: user.uid,
        inscritos: 0,
        status: 'rascunho',
        createdAt: serverTimestamp()
      });
      setShowCourseModal(false);
      setCourseForm({ nome: '', descricao: '', capaUrl: '', cargaHoraria: '', publicoAlvo: 'Geral' });
      fetchMyCourses();
    } catch (error) { console.error(error); }
  };

  const handleCreateModule = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!selectedCourse) return;
    try {
      await addDoc(collection(db, 'cursos', selectedCourse.id, 'modulos'), {
        nome: moduleForm.nome,
        ordem: modules.length + 1,
        createdAt: serverTimestamp()
      });
      setShowModuleModal(false);
      setModuleForm({ nome: '' });
      fetchModules(selectedCourse.id);
    } catch (error) { console.error(error); }
  };

  const handleCreateLesson = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!selectedCourse || !activeModuleId) return;
    try {
      const currentLessonsCount = lessonsByModule[activeModuleId]?.length || 0;
      await addDoc(collection(db, 'cursos', selectedCourse.id, 'modulos', activeModuleId, 'aulas'), {
        ...lessonForm,
        ordem: currentLessonsCount + 1,
        createdAt: serverTimestamp()
      });
      setShowLessonModal(false);
      setLessonForm({ titulo: '', videoUrl: '', materialUrl: '' });
      fetchLessons(selectedCourse.id, activeModuleId);
    } catch (error) { console.error(error); }
  };

  const handleManageCourse = (course: Course) => {
    setSelectedCourse(course);
    onSubChange('modulos');
    fetchModules(course.id);
  };

  const openPreview = (lesson: Lesson) => {
    setCountdown(15);
    setIsTimerFinished(false);
    setIsConcluded(false);
    setPlayerIsPlaying(false);
    setPreviewLesson(lesson);
  };

  const closePreview = () => {
    setPreviewLesson(null);
    setIsTimerFinished(false);
    setIsConcluded(false);
    setCountdown(15);
    setPlayerIsPlaying(false);
  };

  const handleConcludeLesson = () => {
    if (!isTimerFinished) return;
    setIsConcluded(true);
  };

  const getEmbedUrl = (url: string) => {
    if (!url) return "";
    const ytRegex = /(?:https?:\/\/)?(?:www\.)?(?:youtube\.com\/(?:[^\/\n\s]+\/\S+\/|(?:v|e(?:mbed)?)\/|\S*?[?&]v=)|youtu\.be\/)([a-zA-Z0-9_-]{11})/;
    const ytMatch = url.match(ytRegex);
    if (ytMatch && ytMatch[1]) {
      return `https://www.youtube.com/embed/${ytMatch[1]}?modestbranding=1&rel=0&iv_load_policy=3&disablekb=1&controls=0&showinfo=0&enablejsapi=1&origin=${window.location.origin}`;
    }
    return url;
  };

  // Componente de Dropdown de Ações
  const ActionMenu = ({ course }: { course: Course }) => (
    <div className="relative action-menu-container" onClick={e => e.stopPropagation()}>
      <button 
        onClick={() => setOpenMenuId(openMenuId === course.id ? null : course.id)}
        className="p-2 text-slate-400 hover:text-slate-900 transition-colors rounded-lg hover:bg-slate-100 relative z-10"
      >
        <MoreVertical size={16} />
      </button>

      {openMenuId === course.id && (
        <div className="absolute right-0 top-full mt-2 w-48 bg-white border border-slate-200 rounded-xl shadow-2xl z-[500] origin-top-right animate-in fade-in slide-in-from-top-2 duration-200 overflow-visible">
          <div className="rounded-xl overflow-hidden">
            <button 
              onClick={() => handleManageCourse(course)}
              className="w-full flex items-center gap-3 px-4 py-2.5 text-xs font-bold text-slate-700 hover:bg-indigo-50 hover:text-indigo-600 transition-all text-left"
            >
              <Edit2 size={14} /> Editar Grade
            </button>
            <button 
              onClick={() => handleDuplicateCourse(course)}
              className="w-full flex items-center gap-3 px-4 py-2.5 text-xs font-bold text-slate-700 hover:bg-indigo-50 hover:text-indigo-600 transition-all text-left"
            >
              <Copy size={14} /> Duplicar Curso
            </button>
            <button 
              onClick={() => { setSelectedCourse(course); }}
              className="w-full flex items-center gap-3 px-4 py-2.5 text-xs font-bold text-slate-700 hover:bg-indigo-50 hover:text-indigo-600 transition-all text-left"
            >
              <ExternalLink size={14} /> Ver como Aluno
            </button>
            <div className="border-t border-slate-100 my-1"></div>
            <button 
              onClick={() => handleDeleteCourseFull(course)}
              className="w-full flex items-center gap-3 px-4 py-2.5 text-xs font-bold text-red-500 hover:bg-red-50 transition-all text-left"
            >
              <Trash2 size={14} /> Excluir Curso
            </button>
          </div>
        </div>
      )}
    </div>
  );

  // RENDER: GESTÃO DO CURSO (Módulos & Aulas)
  if (activeSub === 'modulos' && selectedCourse) {
    return (
      <div className="space-y-6 animate-in fade-in duration-500 overflow-visible">
        <header className="flex items-center justify-between gap-4">
          <div className="flex items-center gap-4">
            <button 
              onClick={() => onSubChange('cursos')}
              className="flex items-center justify-center h-10 w-10 bg-white border border-slate-200 hover:bg-slate-50 rounded-xl text-slate-600 transition-all shadow-sm group"
            >
              <ArrowLeft size={20} className="group-hover:-translate-x-1 transition-transform" />
            </button>
            <div>
              <h1 className="text-2xl font-bold text-slate-900 leading-tight">{selectedCourse.nome}</h1>
              <div className="flex items-center gap-2 mt-0.5">
                <span className="text-slate-400 text-xs font-medium uppercase tracking-wider">Gestão de Conteúdo</span>
                <span className="h-1 w-1 rounded-full bg-slate-300"></span>
                <span className="text-indigo-600 text-xs font-bold uppercase tracking-wider">{selectedCourse.publicoAlvo}</span>
              </div>
            </div>
          </div>
          <button 
            onClick={() => setShowModuleModal(true)}
            className="flex items-center gap-2 bg-indigo-600 text-white px-5 py-2.5 rounded-xl text-sm font-bold hover:bg-indigo-700 transition-all shadow-lg"
          >
            <Plus size={18} />
            Novo Módulo
          </button>
        </header>

        <div className="grid grid-cols-1 lg:grid-cols-3 gap-6 overflow-visible">
          <div className="lg:col-span-2 space-y-4 overflow-visible">
            <div className="bg-white rounded-2xl border border-slate-200 shadow-sm overflow-visible">
              <div className="px-6 py-4 border-b border-slate-100 flex items-center justify-between bg-slate-50/50">
                <div className="flex items-center gap-2">
                  <Layout size={16} className="text-slate-400" />
                  <h2 className="text-xs font-bold text-slate-800 uppercase tracking-widest">Matriz Curricular</h2>
                </div>
                <span className="text-[10px] font-bold text-slate-400">{modules.length} Módulos</span>
              </div>

              <div className="p-4 space-y-4">
                {modules.length === 0 ? (
                  <div className="p-16 text-center opacity-40">
                    <Layers size={32} className="mx-auto mb-2 text-slate-300" />
                    <p className="text-sm font-medium">Nenhum módulo criado.</p>
                  </div>
                ) : (
                  modules.map((mod) => (
                    <div key={mod.id} className="border border-slate-100 rounded-xl overflow-visible bg-slate-50/30 group">
                      <div className="px-4 py-3 border-b border-slate-100 flex items-center justify-between bg-white group-hover:bg-slate-50 transition-colors rounded-t-xl">
                        <div className="flex items-center gap-3">
                          <span className="bg-slate-900 text-white w-6 h-6 rounded-lg flex items-center justify-center text-[10px] font-black">{mod.ordem}</span>
                          <h3 className="font-bold text-slate-800 text-sm">{mod.nome}</h3>
                        </div>
                        <div className="flex items-center gap-1 opacity-0 group-hover:opacity-100 transition-opacity">
                          <button onClick={() => { setActiveModuleId(mod.id); setShowLessonModal(true); }} className="p-1.5 text-indigo-600 hover:bg-indigo-50 rounded-lg" title="Adicionar Aula"><Plus size={18} /></button>
                          <button onClick={() => handleDeleteModule(mod.id)} className="p-1.5 text-red-500 hover:bg-red-50 rounded-lg" title="Excluir Módulo"><Trash2 size={18} /></button>
                        </div>
                      </div>

                      <div className="p-2 space-y-1">
                        {lessonsByModule[mod.id]?.map((lesson) => (
                          <div key={lesson.id} className="flex items-center justify-between p-3 rounded-xl hover:bg-white hover:shadow-sm transition-all group/lesson bg-transparent">
                            <div className="flex items-center gap-4">
                              <div className="p-2 bg-white border border-slate-100 text-indigo-600 rounded-lg shadow-sm"><Play size={12} fill="currentColor" /></div>
                              <p className="text-sm font-semibold text-slate-700">{lesson.titulo}</p>
                            </div>
                            <div className="flex items-center gap-1 opacity-0 group-hover/lesson:opacity-100 transition-all">
                              <button onClick={() => openPreview(lesson)} className="p-1.5 text-indigo-600 hover:bg-indigo-50 rounded-lg"><Eye size={16} /></button>
                              <button onClick={() => handleDeleteLesson(mod.id, lesson.id)} className="p-1.5 text-slate-300 hover:text-red-500 transition-all"><Trash2 size={14} /></button>
                            </div>
                          </div>
                        ))}
                      </div>
                    </div>
                  ))
                )}
              </div>
            </div>
          </div>

          <div className="space-y-4">
            <div className="bg-white p-5 rounded-2xl border border-slate-200 shadow-sm sticky top-24">
              <img src={selectedCourse.capaUrl} className="w-full h-32 object-cover rounded-xl mb-4 border border-slate-100" />
              <div className="space-y-3">
                <div className="flex justify-between text-xs border-b border-slate-50 pb-2">
                   <span className="text-slate-400 font-bold uppercase">Inscritos</span>
                   <span className="font-black text-slate-900">{selectedCourse.inscritos} Alunos</span>
                </div>
                <div className="flex justify-between text-xs border-b border-slate-50 pb-2">
                   <span className="text-slate-400 font-bold uppercase">Carga Horária</span>
                   <span className="font-black text-slate-900">{selectedCourse.cargaHoraria}</span>
                </div>
              </div>
            </div>
          </div>
        </div>

        {/* MODAIS */}
        {showModuleModal && (
          <div className="fixed inset-0 z-[110] flex items-center justify-center p-4 bg-slate-900/40 backdrop-blur-sm">
            <div className="bg-white w-full max-w-md rounded-2xl shadow-2xl overflow-hidden">
              <div className="p-4 border-b border-slate-100 flex items-center justify-between">
                <h3 className="font-bold text-slate-900">Novo Módulo Acadêmico</h3>
                <button onClick={() => setShowModuleModal(false)} className="text-slate-400 hover:text-slate-600"><X size={20} /></button>
              </div>
              <form onSubmit={handleCreateModule} className="p-6 space-y-4">
                <input required autoFocus value={moduleForm.nome} onChange={e => setModuleForm({nome: e.target.value})} placeholder="Título do Módulo" className="w-full px-4 py-2.5 bg-slate-50 border border-slate-200 rounded-xl text-sm outline-none" />
                <button type="submit" className="w-full bg-indigo-600 text-white py-2.5 rounded-xl font-bold text-sm">Criar Módulo</button>
              </form>
            </div>
          </div>
        )}

        {showLessonModal && (
          <div className="fixed inset-0 z-[110] flex items-center justify-center p-4 bg-slate-900/40 backdrop-blur-sm">
            <div className="bg-white w-full max-w-lg rounded-2xl shadow-2xl overflow-hidden">
              <div className="p-4 border-b border-slate-100 flex items-center justify-between">
                <h3 className="font-bold text-slate-900">Adicionar Aula</h3>
                <button onClick={() => setShowLessonModal(false)} className="text-slate-400 hover:text-slate-600"><X size={20} /></button>
              </div>
              <form onSubmit={handleCreateLesson} className="p-6 space-y-4">
                <input required autoFocus value={lessonForm.titulo} onChange={e => setLessonForm({...lessonForm, titulo: e.target.value})} placeholder="Título da Aula" className="w-full px-4 py-2.5 bg-slate-50 border border-slate-200 rounded-xl text-sm" />
                <input value={lessonForm.videoUrl} onChange={e => setLessonForm({...lessonForm, videoUrl: e.target.value})} placeholder="Link Vídeo (YouTube)" className="w-full px-4 py-2 bg-slate-50 border border-slate-200 rounded-xl text-sm" />
                <input value={lessonForm.materialUrl} onChange={e => setLessonForm({...lessonForm, materialUrl: e.target.value})} placeholder="Link Material (PDF)" className="w-full px-4 py-2 bg-slate-50 border border-slate-200 rounded-xl text-sm" />
                <button type="submit" className="w-full bg-indigo-600 text-white py-3 rounded-xl font-bold text-sm">Publicar Aula</button>
              </form>
            </div>
          </div>
        )}

        {previewLesson && (
          <div className="fixed inset-0 z-[200] flex items-center justify-center p-4 bg-slate-900/80 backdrop-blur-md">
            <div className="bg-white w-full max-w-6xl h-[90vh] rounded-3xl shadow-2xl overflow-hidden flex flex-col animate-in zoom-in-95 duration-200">
              <div className="p-5 border-b border-slate-100 flex items-center justify-between bg-white">
                <div className="flex items-center gap-3">
                  <div className="bg-indigo-600 p-2 rounded-xl text-white shadow-lg shadow-indigo-200"><Eye size={18} /></div>
                  <h3 className="font-bold text-slate-900 text-base leading-tight">Pré-visualização de Aula: {previewLesson.titulo}</h3>
                </div>
                <button onClick={closePreview} className="flex items-center gap-2 px-4 py-2 bg-slate-100 hover:bg-slate-200 rounded-xl text-slate-600 text-xs font-bold transition-colors">
                  <X size={16} /> Fechar Aula
                </button>
              </div>
              <div className="flex-1 overflow-y-auto bg-slate-50/50 p-6 flex flex-col lg:flex-row gap-6">
                <div className="flex-[2] flex flex-col justify-center">
                  <div ref={playerContainerRef} className="aspect-video bg-slate-900 rounded-2xl overflow-hidden shadow-2xl border-4 border-white relative group">
                    <iframe ref={iframeRef} width="100%" height="100%" src={getEmbedUrl(previewLesson.videoUrl)} title="Video Player" frameBorder="0" allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture" allowFullScreen className="pointer-events-none"></iframe>
                    <div className="absolute inset-0 z-20 pointer-events-none flex flex-col justify-end">
                      {!playerIsPlaying && (
                        <div className="absolute inset-0 flex items-center justify-center bg-black/20 backdrop-blur-[2px] pointer-events-auto cursor-pointer" onClick={togglePlay}>
                          <div className="w-20 h-20 bg-white/10 backdrop-blur-xl border border-white/20 rounded-full flex items-center justify-center text-white scale-100 group-hover:scale-110 transition-all shadow-2xl"><Play size={40} fill="currentColor" /></div>
                        </div>
                      )}
                      <div className="p-4 bg-gradient-to-t from-black/80 to-transparent opacity-0 group-hover:opacity-100 transition-opacity duration-300 pointer-events-auto flex items-center justify-between px-8">
                        <div className="flex items-center gap-4">
                          <button onClick={togglePlay} className="text-white hover:text-indigo-400 transition-colors">
                            {playerIsPlaying ? <Pause size={24} fill="currentColor" /> : <Play size={24} fill="currentColor" />}
                          </button>
                          <div className="flex items-center gap-3 group/vol">
                            <button onClick={toggleMute} className="text-white hover:text-indigo-400">
                              {(isMuted || playerVolume === 0) ? <VolumeX size={20} /> : <Volume2 size={20} />}
                            </button>
                            <input type="range" min="0" max="100" value={isMuted ? 0 : playerVolume} onChange={handleVolumeChange} className="w-20 h-1.5 bg-white/20 rounded-full appearance-none cursor-pointer accent-indigo-500" />
                          </div>
                        </div>
                        <button onClick={toggleFullscreen} className="text-white hover:text-indigo-400 transition-colors"><Maximize size={20} /></button>
                      </div>
                    </div>
                  </div>
                </div>
                <div className="flex-1 space-y-4">
                   <div className="bg-white p-6 rounded-2xl border border-slate-200 shadow-sm sticky top-0">
                      <h4 className="text-xs font-black text-slate-400 uppercase tracking-[0.2em] mb-4">Métrica Pedagógica</h4>
                      <div className="space-y-4">
                         <div className="bg-slate-50 p-6 rounded-xl text-center border border-slate-100">
                           {!isTimerFinished ? (
                             <div className="space-y-2"><span className="text-4xl font-black text-slate-900 tracking-tighter">{countdown}s</span><p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">Tempo para Validação</p></div>
                           ) : (
                             <div className="py-2 text-emerald-600 font-bold uppercase text-xs">Validado</div>
                           )}
                         </div>
                         <button disabled={!isTimerFinished || isConcluded} onClick={handleConcludeLesson} className={`w-full py-4 rounded-xl font-bold text-sm shadow-lg ${isTimerFinished && !isConcluded ? 'bg-slate-900 text-white' : isConcluded ? 'bg-emerald-100 text-emerald-700' : 'bg-slate-100 text-slate-400'}`}>
                           {isConcluded ? 'Aula Concluída' : 'Validar Presença'}
                         </button>
                         {isConcluded && previewLesson.materialUrl && (
                           <a href={previewLesson.materialUrl} target="_blank" rel="noopener noreferrer" className="w-full py-4 bg-indigo-600 text-white rounded-xl font-bold text-sm shadow-lg flex items-center justify-center gap-2 hover:bg-indigo-700 transition-all">
                             <Download size={18} /> 📥 Baixar Material
                           </a>
                         )}
                      </div>
                   </div>
                </div>
              </div>
            </div>
          </div>
        )}
      </div>
    );
  }

  // RENDER: LISTA DE CURSOS (Tab: Módulos)
  if (activeSub === 'modulos' && !selectedCourse) {
    return (
      <div className="space-y-6 animate-in fade-in duration-500 overflow-visible">
        <header>
          <h1 className="text-2xl font-black text-slate-900 tracking-tight uppercase">Módulos Acadêmicos</h1>
          <p className="text-slate-500 text-sm font-medium">Gestão detalhada da matriz curricular por disciplina.</p>
        </header>

        <div className="bg-white rounded-2xl border border-slate-200 shadow-sm overflow-visible">
          <table className="w-full text-left">
             <thead className="bg-slate-50 text-[10px] uppercase font-bold text-slate-400 tracking-widest border-b border-slate-100">
               <tr>
                 <th className="px-6 py-4">Curso / Disciplina</th>
                 <th className="px-6 py-4">Público</th>
                 <th className="px-6 py-4">Alunos</th>
                 <th className="px-6 py-4 text-right">Ações</th>
               </tr>
             </thead>
             <tbody className="divide-y divide-slate-100">
               {loading ? (
                 <tr><td colSpan={4} className="p-12 text-center text-slate-400 text-xs italic">Sincronizando banco de dados...</td></tr>
               ) : myCourses.map(course => (
                 <tr key={course.id} className="hover:bg-slate-50 transition-all group overflow-visible">
                   <td className="px-6 py-4">
                     <div className="flex items-center gap-3">
                       <img src={course.capaUrl} className="w-10 h-10 rounded-lg object-cover border border-slate-100" />
                       <span className="font-bold text-slate-800 text-sm">{course.nome}</span>
                     </div>
                   </td>
                   <td className="px-6 py-4 text-xs font-bold text-indigo-600 uppercase tracking-tighter">{course.publicoAlvo}</td>
                   <td className="px-6 py-4 text-xs text-slate-500 font-medium">{course.inscritos} Alunos</td>
                   <td className="px-6 py-4 text-right flex items-center justify-end gap-2 overflow-visible">
                     <button onClick={() => handleManageCourse(course)} className="flex items-center gap-1.5 bg-indigo-600 text-white px-4 py-1.5 rounded-lg text-[10px] font-black uppercase tracking-widest hover:bg-indigo-700 transition-all shadow-lg shadow-indigo-100">
                       <Edit2 size={12} /> Gerenciar Módulos
                     </button>
                     <ActionMenu course={course} />
                   </td>
                 </tr>
               ))}
             </tbody>
          </table>
        </div>
      </div>
    );
  }

  // RENDER: GRID DE CURSOS (Tab: Cursos)
  return (
    <div className="space-y-6 animate-in fade-in duration-500 overflow-visible">
      <header className="flex flex-col sm:flex-row sm:items-center justify-between gap-4">
        <div>
          <h1 className="text-2xl font-black text-slate-900 tracking-tight uppercase">Catálogo Global</h1>
          <p className="text-slate-500 text-sm font-medium">Gerencie currículos, duplique treinamentos ou remova conteúdos.</p>
        </div>
        <button onClick={() => setShowCourseModal(true)} className="flex items-center justify-center gap-2 bg-indigo-600 text-white px-6 py-3 rounded-2xl text-sm font-black hover:bg-indigo-700 transition-all shadow-xl shadow-indigo-100 uppercase tracking-widest">
          <Plus size={18} /> Cadastrar Novo
        </button>
      </header>

      <div className="bg-white rounded-3xl border border-slate-200 shadow-sm min-h-[400px] flex flex-col overflow-visible">
        <div className="p-5 border-b border-slate-100 flex flex-col sm:flex-row items-center justify-between gap-4 bg-slate-50/30">
          <div className="relative w-full max-w-xs">
            <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={16} />
            <input type="text" placeholder="Localizar curso..." className="w-full pl-10 pr-4 py-2.5 bg-white border border-slate-200 rounded-xl text-xs outline-none shadow-sm font-medium" />
          </div>
        </div>

        {loading ? (
          <div className="flex-1 flex items-center justify-center p-12"><div className="h-6 w-6 animate-spin rounded-full border-2 border-indigo-600 border-t-transparent"></div></div>
        ) : myCourses.length > 0 ? (
          <div className="grid grid-cols-1 sm:grid-cols-2 md:grid-cols-3 lg:grid-cols-4 xl:grid-cols-6 gap-6 p-8 overflow-visible">
            {myCourses.map(course => (
              <div 
                key={course.id} 
                className="border border-slate-200 p-3 rounded-3xl hover:shadow-xl hover:border-indigo-400 transition-all bg-white flex flex-col relative overflow-visible group/card"
              >
                {duplicatingId === course.id && (
                  <div className="absolute inset-0 z-10 bg-white/80 backdrop-blur-sm flex flex-col items-center justify-center gap-2 rounded-3xl">
                    <div className="h-6 w-6 animate-spin rounded-full border-2 border-indigo-600 border-t-transparent"></div>
                    <span className="text-[9px] font-black uppercase text-indigo-600">Sincronizando...</span>
                  </div>
                )}

                <div className="relative aspect-[4/3] rounded-2xl mb-3 bg-slate-100 border border-slate-100 overflow-visible">
                  <div className="w-full h-full rounded-2xl overflow-hidden relative">
                    <img src={course.capaUrl} className="w-full h-full object-cover group-hover/card:scale-110 transition-transform duration-700" />
                  </div>
                  <div className="absolute top-2 right-2 flex gap-1 z-20">
                    <ActionMenu course={course} />
                  </div>
                </div>
                <h3 className="font-black text-slate-900 text-[11px] mb-1 line-clamp-2 leading-tight uppercase group-hover/card:text-indigo-600 transition-colors px-1">{course.nome}</h3>

                <div 
                  onClick={() => handleManageCourse(course)} 
                  className="mt-auto flex items-center justify-between text-[8px] text-slate-400 font-black uppercase tracking-widest pt-3 border-t border-slate-50 cursor-pointer px-1"
                >
                  <div className="flex items-center gap-1.5"><Layout size={10} className="text-slate-300" /><span>Gerenciar</span></div>
                  <ChevronRight size={12} className="group-hover/card:translate-x-1 transition-transform text-indigo-500" />
                </div>
              </div>
            ))}
          </div>
        ) : (
          <div className="flex-1 flex flex-col items-center justify-center p-16 opacity-30 text-center">
            <BookOpen size={48} className="mb-4 text-slate-300 mx-auto" />
            <h3 className="text-slate-900 font-black uppercase tracking-widest text-sm">Nenhum curso cadastrado</h3>
          </div>
        )}
      </div>

      {/* MODAL CRIAR CURSO */}
      {showCourseModal && (
        <div className="fixed inset-0 z-[1000] flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-sm">
          <div className="bg-white w-full max-w-xl rounded-3xl shadow-2xl overflow-hidden animate-in zoom-in-95">
            <div className="p-6 border-b border-slate-100 flex items-center justify-between">
              <h3 className="font-black text-slate-900 uppercase tracking-widest text-sm">Novo Currículo</h3>
              <button onClick={() => setShowCourseModal(false)} className="text-slate-400 hover:text-slate-600"><X size={20} /></button>
            </div>
            <form onSubmit={handleCreateCourse} className="p-8 space-y-6">
              <input required value={courseForm.nome} onChange={e => setCourseForm({...courseForm, nome: e.target.value})} placeholder="Título do Curso" className="w-full px-4 py-3 bg-slate-50 border border-slate-200 rounded-2xl text-sm outline-none" />
              <div className="grid grid-cols-2 gap-4">
                <input required value={courseForm.cargaHoraria} onChange={e => setCourseForm({...courseForm, cargaHoraria: e.target.value})} placeholder="Ex: 40h" className="w-full px-4 py-3 bg-slate-50 border border-slate-200 rounded-2xl text-sm outline-none" />
                <select value={courseForm.publicoAlvo} onChange={e => setCourseForm({...courseForm, publicoAlvo: e.target.value as any})} className="w-full px-4 py-3 bg-slate-50 border border-slate-200 rounded-2xl text-sm outline-none">
                  <option value="Geral">Geral</option>
                  <option value="Líderes">Líderes</option>
                  <option value="Obreiros">Obreiros</option>
                </select>
              </div>
              <input value={courseForm.capaUrl} onChange={e => setCourseForm({...courseForm, capaUrl: e.target.value})} placeholder="URL Imagem Capa" className="w-full px-4 py-3 bg-slate-50 border border-slate-200 rounded-2xl text-sm outline-none" />
              <button type="submit" className="w-full bg-slate-900 text-white py-4 rounded-2xl font-black text-sm uppercase tracking-widest shadow-xl shadow-slate-200">Criar Curso</button>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

