                <input value={lessonForm.materialUrl} onChange={e => setLessonForm({...lessonForm, materialUrl: e.target.value})} placeholder="Link para PDF ou Slides" className="w-full px-4 py-3 bg-slate-50 border border-slate-200 rounded-2xl text-sm outline-none" />
              </div>
              <button type="submit" className="w-full bg-indigo-600 text-white py-4 rounded-2xl font-black text-sm uppercase tracking-widest shadow-xl shadow-indigo-100 mt-4">Salvar Aula</button>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

