import React, { useState, useEffect } from 'react';
import { onAuthStateChanged } from 'firebase/auth';
import { doc, getDoc } from 'firebase/firestore';
import { auth, db } from './firebase';
import { UserRole, MainView, User, ProfessorSubView } from './types';
import Navbar from './components/Navbar';
import Sidebar from './components/Sidebar';
import DashboardView from './views/DashboardView';
import ProfessorView from './views/ProfessorView';
import StudentsView from './views/StudentsView';
import SecretariatView from './views/SecretariatView';
import SettingsView from './views/SettingsView';
import LoginView from './views/LoginView';

const App: React.FC = () => {
  const [currentUser, setCurrentUser] = useState<User | null>(null);
  const [loading, setLoading] = useState(true);
  const [activeView, setActiveView] = useState<MainView>('dashboard');
  const [activeProfessorSub, setActiveProfessorSub] = useState<ProfessorSubView>('cursos');
  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);

  useEffect(() => {
    const unsubscribe = onAuthStateChanged(auth, async (user) => {
      if (user) {
        try {
          // RBAC: Consulta a coleção 'users' (conforme solicitado no prompt)
          const userDoc = await getDoc(doc(db, 'users', user.uid));
          const userData = userDoc.data();

          const role = (userData?.role as UserRole) || 'aluno';

          setCurrentUser({
            uid: user.uid,
            email: user.email,
            displayName: userData?.nome || user.displayName || 'Usuário',
            role: role,
            photoURL: user.photoURL || undefined
          });
        } catch (error) {
          console.error("Erro ao buscar perfil RBAC:", error);
          setCurrentUser(null);
        }
      } else {
        setCurrentUser(null);
      }
      setLoading(false);
    });

    return () => unsubscribe();
  }, []);

  if (loading) {
    return (
      <div className="flex h-screen items-center justify-center bg-slate-50">
        <div className="flex flex-col items-center gap-4">
          <div className="h-10 w-10 animate-spin rounded-full border-4 border-indigo-600 border-t-transparent"></div>
          <p className="text-xs font-bold uppercase tracking-widest text-slate-500">Escola Bíblica EAD</p>
        </div>
      </div>
    );
  }

  if (!currentUser) {
    return <LoginView />;
  }

  // Filtro de Segurança RBAC: Bloqueia alunos da área administrativa
  if (currentUser.role !== 'diretor' && currentUser.role !== 'professor') {
    return (
      <div className="flex h-screen items-center justify-center bg-slate-50 p-6">
        <div className="max-w-md w-full bg-white p-8 rounded-2xl shadow-xl border border-red-100 text-center">
          <div className="w-16 h-16 bg-red-100 text-red-600 rounded-full flex items-center justify-center mx-auto mb-4">
            <svg xmlns="http://www.w3.org/2000/svg" className="h-8 w-8" fill="none" viewBox="0 0 24 24" stroke="currentColor">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 15v2m0 0v3m0-3h3m-3 0h-3m-2-5a4 4 0 118 0 4 4 0 01-8 0zM3 20a6 6 0 0112 0v1H3v-1z" />
            </svg>
          </div>
          <h1 className="text-xl font-bold text-slate-900 mb-2">Área Administrativa Restrita</h1>
          <p className="text-slate-500 text-sm mb-6">Seu perfil ({currentUser.role}) não possui permissões para acessar este sistema. Entre em contato com a secretaria da igreja.</p>
          <button 
            onClick={() => auth.signOut()}
            className="w-full bg-slate-900 text-white py-2.5 rounded-xl text-sm font-bold hover:bg-slate-800 transition-all"
          >
            Sair do Sistema
          </button>
        </div>
      </div>
    );
  }

  const renderView = () => {
    switch (activeView) {
      case 'dashboard': return <DashboardView />;
      case 'professor': return (
        <ProfessorView 
          user={currentUser} 
          activeSub={activeProfessorSub}
          onSubChange={setActiveProfessorSub}
        />
      );
      case 'alunos': return <StudentsView />;
      case 'secretaria': return <SecretariatView />;
      case 'configuracoes': return <SettingsView />;
      default: return <DashboardView />;
    }
  };

  return (
    <div className="min-h-screen bg-slate-50 flex flex-col font-sans antialiased text-slate-900">
      <Navbar 
        user={currentUser} 
        activeView={activeView} 
        setActiveView={(v) => { setActiveView(v); setIsMobileMenuOpen(false); }}
        isMobileMenuOpen={isMobileMenuOpen}
        setIsMobileMenuOpen={setIsMobileMenuOpen}
      />

      <div className="flex-1 flex overflow-hidden">
        {/* Sidebar Contextual: Visível apenas em abas específicas como solicitado */}
        {(activeView === 'professor') && (
          <Sidebar 
            activeSub={activeProfessorSub}
            onSubChange={setActiveProfessorSub}
          />
        )}

        <main className="flex-1 overflow-y-auto overflow-x-hidden">
          <div className="max-w-7xl mx-auto p-4 md:p-6 lg:p-8">
            {renderView()}
          </div>
        </main>
      </div>
    </div>
  );
};

export default App;

